-- ----------------------------------------------------------------------------
-- >>> 0001_init_schema.sql
-- ----------------------------------------------------------------------------
-- =============================================================================
-- 0001  Schema for the review / order tracking platform.
-- Supports both the admin panel (this phase) and the user panel (next phase).
-- =============================================================================

-- gen_random_uuid() has been built into Postgres since 13, which is why the
-- defaults below work without an extension. pgcrypto is attempted only for
-- older servers, and a missing extension must not abort the migration.
do $$
begin
  create extension if not exists "pgcrypto";
exception when others then
  raise notice 'pgcrypto unavailable; using the built-in gen_random_uuid()';
end;
$$;

-- -----------------------------------------------------------------------------
-- profiles  (extends auth.users)
-- -----------------------------------------------------------------------------
create table if not exists public.profiles (
  id uuid primary key references auth.users(id) on delete cascade,
  full_name text not null check (length(btrim(full_name)) between 1 and 120),
  phone text,
  phone_verified boolean not null default false,
  role text not null default 'user' check (role in ('user','admin')),
  created_at timestamptz not null default now()
);

comment on table public.profiles is
  'Application profile for every auth.users row. role drives every admin RLS policy.';

-- -----------------------------------------------------------------------------
-- bank_details  (columns are write-only for regular users, see 0002)
-- -----------------------------------------------------------------------------
create table if not exists public.bank_details (
  user_id uuid primary key
    constraint bank_details_user_id_fkey references public.profiles(id) on delete cascade,
  account_holder_name text,
  -- AES-256-GCM ciphertext produced by src/lib/crypto.ts. Never decrypt client-side.
  account_number_encrypted text,
  account_number_last4 text check (account_number_last4 is null or account_number_last4 ~ '^[0-9]{4}$'),
  ifsc_code text,
  upi_id text,
  updated_at timestamptz not null default now()
);

comment on column public.bank_details.account_number_encrypted is
  'Application-layer AES-256-GCM ciphertext, format v1.<iv>.<ciphertext> (base64url). Readable only by service_role.';

-- -----------------------------------------------------------------------------
-- products
-- -----------------------------------------------------------------------------
create table if not exists public.products (
  id uuid primary key default gen_random_uuid(),
  name text not null check (length(btrim(name)) between 1 and 200),
  brand text,
  description text,
  -- Storage object path inside the private product-images bucket, or an absolute URL.
  image_url text,
  total_slots int not null check (total_slots > 0),
  slots_filled int not null default 0,
  cashback_amount numeric(12,2) check (cashback_amount is null or cashback_amount >= 0),
  status text not null default 'open' check (status in ('open','closed')),
  created_by uuid
    constraint products_created_by_fkey references public.profiles(id) on delete set null,
  created_at timestamptz not null default now(),
  -- Hard guarantee that concurrent claims can never oversell a product.
  constraint products_slots_bounds check (slots_filled >= 0 and slots_filled <= total_slots)
);

create index if not exists products_status_idx on public.products (status);
create index if not exists products_created_at_idx on public.products (created_at desc);

-- -----------------------------------------------------------------------------
-- orders
-- -----------------------------------------------------------------------------
create table if not exists public.orders (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null
    constraint orders_user_id_fkey references public.profiles(id) on delete cascade,
  product_id uuid not null
    constraint orders_product_id_fkey references public.products(id) on delete restrict,
  status text not null default 'claimed' check (status in (
    'claimed','order_submitted','order_confirmed','review_pending',
    'review_submitted','approved','paid','rejected'
  )),

  order_screenshot_url text,
  extracted_name text,
  extracted_order_id text,
  extracted_phone text,
  extracted_product_name text,
  user_confirmed boolean not null default false,
  order_confirmed_at timestamptz,

  review_screenshot_url text,
  review_link text,
  review_submitted_at timestamptz,
  approved_at timestamptz,

  payment_reference text,
  paid_at timestamptz,

  rejection_reason text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),

  constraint orders_rejection_reason_required
    check (status <> 'rejected' or length(btrim(coalesce(rejection_reason, ''))) > 0),
  constraint orders_paid_requires_reference
    check (status <> 'paid' or length(btrim(coalesce(payment_reference, ''))) > 0)
);

create index if not exists orders_status_idx on public.orders (status);
create index if not exists orders_user_id_idx on public.orders (user_id, created_at desc);
create index if not exists orders_product_id_idx on public.orders (product_id);
create index if not exists orders_paid_at_idx on public.orders (paid_at desc);

-- One live order per user per product; a rejected order frees the user to retry.
create unique index if not exists orders_one_active_per_product
  on public.orders (user_id, product_id)
  where status <> 'rejected';

-- -----------------------------------------------------------------------------
-- notifications
-- -----------------------------------------------------------------------------
create table if not exists public.notifications (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null
    constraint notifications_user_id_fkey references public.profiles(id) on delete cascade,
  type text not null,
  message text not null check (length(btrim(message)) between 1 and 1000),
  related_order_id uuid
    constraint notifications_related_order_id_fkey references public.orders(id) on delete set null,
  is_read boolean not null default false,
  created_at timestamptz not null default now()
);

create index if not exists notifications_user_idx on public.notifications (user_id, created_at desc);
create index if not exists notifications_unread_idx on public.notifications (user_id) where is_read = false;

-- -----------------------------------------------------------------------------
-- audit_log  (append-only: no update/delete policy or grant exists anywhere)
-- -----------------------------------------------------------------------------
create table if not exists public.audit_log (
  id uuid primary key default gen_random_uuid(),
  admin_id uuid not null
    constraint audit_log_admin_id_fkey references public.profiles(id) on delete restrict,
  action text not null,
  target_table text not null,
  target_id uuid not null,
  details jsonb,
  created_at timestamptz not null default now()
);

create index if not exists audit_log_created_at_idx on public.audit_log (created_at desc);
create index if not exists audit_log_target_idx on public.audit_log (target_table, target_id);
create index if not exists audit_log_admin_idx on public.audit_log (admin_id, created_at desc);

-- -----------------------------------------------------------------------------
-- updated_at maintenance
-- -----------------------------------------------------------------------------
create or replace function public.touch_updated_at()
returns trigger
language plpgsql
as $$
begin
  new.updated_at := now();
  return new;
end;
$$;

drop trigger if exists bank_details_touch_updated_at on public.bank_details;
create trigger bank_details_touch_updated_at
  before update on public.bank_details
  for each row execute function public.touch_updated_at();

-- -----------------------------------------------------------------------------
-- Auto-create a profile for every new auth user (future user panel sign-ups).
-- security definer so it can write public.profiles regardless of the caller.
-- -----------------------------------------------------------------------------
create or replace function public.handle_new_auth_user()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  insert into public.profiles (id, full_name, phone, role)
  values (
    new.id,
    coalesce(nullif(btrim(coalesce(new.raw_user_meta_data ->> 'full_name', '')), ''), split_part(new.email, '@', 1), 'User'),
    nullif(btrim(coalesce(new.raw_user_meta_data ->> 'phone', '')), ''),
    'user'
  )
  on conflict (id) do nothing;
  return new;
end;
$$;

drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created
  after insert on auth.users
  for each row execute function public.handle_new_auth_user();


-- ----------------------------------------------------------------------------
-- >>> 0002_rls_and_policies.sql
-- ----------------------------------------------------------------------------
-- =============================================================================
-- 0002  Row Level Security.
--
-- Rules enforced here:
--   * RLS is enabled on every table. No table relies on GRANTs alone.
--   * A user can only touch their own orders / bank_details / notifications.
--   * Admin power comes exclusively from public.profiles.role = 'admin'.
--   * audit_log is append-only: there is no update/delete policy at all.
--   * bank_details.account_number_encrypted is NOT readable by anon or
--     authenticated, not even by an admin session. Only service_role can read
--     the ciphertext, which is why decryption is confined to one server route.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- Helpers. SECURITY DEFINER so the policy check itself is not filtered by the
-- profiles RLS policy (which would recurse).
-- -----------------------------------------------------------------------------
create or replace function public.is_admin(uid uuid default auth.uid())
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1 from public.profiles p where p.id = uid and p.role = 'admin'
  );
$$;

comment on function public.is_admin(uuid) is
  'True when the given auth user has profiles.role = admin. The single source of truth for admin access.';

-- -----------------------------------------------------------------------------
-- Enable RLS everywhere (default deny: no policy == no access).
-- -----------------------------------------------------------------------------
alter table public.profiles     enable row level security;
alter table public.bank_details enable row level security;
alter table public.products     enable row level security;
alter table public.orders       enable row level security;
alter table public.notifications enable row level security;
alter table public.audit_log    enable row level security;

drop policy if exists profiles_select_own_or_admin on public.profiles;
drop policy if exists profiles_insert_self on public.profiles;
drop policy if exists profiles_update_own on public.profiles;
drop policy if exists profiles_update_admin on public.profiles;
drop policy if exists profiles_delete_admin on public.profiles;

drop policy if exists bank_details_select_own_or_admin on public.bank_details;
drop policy if exists bank_details_insert_own on public.bank_details;
drop policy if exists bank_details_update_own on public.bank_details;

drop policy if exists products_select on public.products;
drop policy if exists products_insert_admin on public.products;
drop policy if exists products_update_admin on public.products;
drop policy if exists products_delete_admin on public.products;

drop policy if exists orders_select_own_or_admin on public.orders;
drop policy if exists orders_insert_own on public.orders;
drop policy if exists orders_update_own_or_admin on public.orders;
drop policy if exists orders_delete_admin on public.orders;

drop policy if exists notifications_select_own on public.notifications;
drop policy if exists notifications_update_own on public.notifications;
drop policy if exists notifications_insert_admin on public.notifications;

drop policy if exists audit_log_select_admin on public.audit_log;
drop policy if exists audit_log_insert_admin on public.audit_log;

-- -----------------------------------------------------------------------------
-- profiles
-- -----------------------------------------------------------------------------
create policy profiles_select_own_or_admin on public.profiles
  for select to authenticated
  using (id = auth.uid() or public.is_admin());

create policy profiles_insert_self on public.profiles
  for insert to authenticated
  with check (id = auth.uid());

create policy profiles_update_own on public.profiles
  for update to authenticated
  using (id = auth.uid())
  with check (id = auth.uid());

create policy profiles_update_admin on public.profiles
  for update to authenticated
  using (public.is_admin())
  with check (public.is_admin());

create policy profiles_delete_admin on public.profiles
  for delete to authenticated
  using (public.is_admin());

-- -----------------------------------------------------------------------------
-- bank_details  (owners write; owners + admins read the safe columns only)
-- -----------------------------------------------------------------------------
create policy bank_details_select_own_or_admin on public.bank_details
  for select to authenticated
  using (user_id = auth.uid() or public.is_admin());

create policy bank_details_insert_own on public.bank_details
  for insert to authenticated
  with check (user_id = auth.uid());

create policy bank_details_update_own on public.bank_details
  for update to authenticated
  using (user_id = auth.uid())
  with check (user_id = auth.uid());

-- Column level privileges: the ciphertext column is invisible to clients even
-- when an admin is signed in. Only service_role (server side) may read it.
revoke all on public.bank_details from anon, authenticated;
grant select (user_id, account_holder_name, account_number_last4, ifsc_code, upi_id, updated_at)
  on public.bank_details to authenticated;
grant insert (user_id, account_holder_name, account_number_encrypted, account_number_last4, ifsc_code, upi_id)
  on public.bank_details to authenticated;
grant update (account_holder_name, account_number_encrypted, account_number_last4, ifsc_code, upi_id, updated_at)
  on public.bank_details to authenticated;
grant all on public.bank_details to service_role;

-- -----------------------------------------------------------------------------
-- products
-- -----------------------------------------------------------------------------
create policy products_select on public.products
  for select to authenticated
  using (status = 'open' or public.is_admin());

create policy products_insert_admin on public.products
  for insert to authenticated
  with check (public.is_admin());

create policy products_update_admin on public.products
  for update to authenticated
  using (public.is_admin())
  with check (public.is_admin());

create policy products_delete_admin on public.products
  for delete to authenticated
  using (public.is_admin());

-- -----------------------------------------------------------------------------
-- orders
-- -----------------------------------------------------------------------------
create policy orders_select_own_or_admin on public.orders
  for select to authenticated
  using (user_id = auth.uid() or public.is_admin());

create policy orders_insert_own on public.orders
  for insert to authenticated
  with check (user_id = auth.uid() and status = 'claimed');

-- Owners may update their own row; the BEFORE UPDATE guard trigger (0003)
-- restricts *which* columns and status transitions a non-admin may touch.
create policy orders_update_own_or_admin on public.orders
  for update to authenticated
  using (user_id = auth.uid() or public.is_admin())
  with check (user_id = auth.uid() or public.is_admin());

create policy orders_delete_admin on public.orders
  for delete to authenticated
  using (public.is_admin());

-- -----------------------------------------------------------------------------
-- notifications  (users read/mark their own; only admins/system may create)
-- -----------------------------------------------------------------------------
create policy notifications_select_own on public.notifications
  for select to authenticated
  using (user_id = auth.uid());

create policy notifications_update_own on public.notifications
  for update to authenticated
  using (user_id = auth.uid())
  with check (user_id = auth.uid());

create policy notifications_insert_admin on public.notifications
  for insert to authenticated
  with check (public.is_admin());

-- -----------------------------------------------------------------------------
-- audit_log  (append-only)
-- -----------------------------------------------------------------------------
create policy audit_log_select_admin on public.audit_log
  for select to authenticated
  using (public.is_admin());

-- An admin session can only ever write rows authored by itself. The heavier
-- admin actions go through SECURITY DEFINER functions in 0003 which run as the
-- table owner, but this policy keeps direct writes honest too.
create policy audit_log_insert_admin on public.audit_log
  for insert to authenticated
  with check (public.is_admin() and admin_id = auth.uid());

revoke update, delete, truncate on public.audit_log from anon, authenticated;

-- -----------------------------------------------------------------------------
-- Function execution rights
-- -----------------------------------------------------------------------------
revoke all on function public.is_admin(uuid) from public;
grant execute on function public.is_admin(uuid) to authenticated, service_role;


-- ----------------------------------------------------------------------------
-- >>> 0003_functions_triggers.sql
-- ----------------------------------------------------------------------------
-- =============================================================================
-- 0003  Business logic that must be atomic.
--
-- Anything that changes state AND writes an audit row lives in a single
-- SECURITY DEFINER function so the two can never drift apart (one transaction,
-- one rollback). Every admin function re-checks profiles.role on the server.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- assert_admin: used by the API layer AND by every admin_* function below.
-- -----------------------------------------------------------------------------
create or replace function public.assert_admin()
returns uuid
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_admin uuid := auth.uid();
begin
  if v_admin is null then
    raise exception 'authentication required' using errcode = '42501';
  end if;
  if not public.is_admin(v_admin) then
    raise exception 'admin privileges required' using errcode = '42501';
  end if;
  return v_admin;
end;
$$;

-- -----------------------------------------------------------------------------
-- claim_product_slot
--
-- Atomic by construction: a single UPDATE ... WHERE slots_filled < total_slots.
-- Postgres takes a row lock, so concurrent callers are serialised and exactly
-- one of them can consume the last slot. The products_slots_bounds CHECK
-- constraint is the backstop if this is ever rewritten.
--
-- The spec's stub used `select found;` in a `language sql` body, which does not
-- compile (FOUND is a plpgsql variable and a `language sql` function cannot run
-- DML + read FOUND). This is the row-count adaptation.
-- -----------------------------------------------------------------------------
create or replace function public.claim_product_slot(p_product_id uuid)
returns boolean
language plpgsql
security definer
set search_path = public
as $$
declare
  v_updated int;
begin
  if auth.uid() is null then
    raise exception 'authentication required' using errcode = '42501';
  end if;

  update public.products
     set slots_filled = slots_filled + 1
   where id = p_product_id
     and status = 'open'
     and slots_filled < total_slots;

  get diagnostics v_updated = row_count;
  return v_updated = 1;
end;
$$;

comment on function public.claim_product_slot(uuid) is
  'Atomically consumes one product slot. Returns false when sold out, closed or unknown.';

-- -----------------------------------------------------------------------------
-- Guard: a non-admin can never change privileged order columns or invent a
-- status transition. Runs before the timestamp trigger.
-- -----------------------------------------------------------------------------
create or replace function public.enforce_order_update_guard()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  -- No JWT in the request context means service_role / server-side code.
  if auth.uid() is null or public.is_admin(auth.uid()) then
    return new;
  end if;

  if new.user_id is distinct from old.user_id then
    raise exception 'orders.user_id is immutable' using errcode = '42501';
  end if;
  if new.product_id is distinct from old.product_id then
    raise exception 'orders.product_id is immutable' using errcode = '42501';
  end if;

  if new.order_confirmed_at is distinct from old.order_confirmed_at
     or new.review_submitted_at is distinct from old.review_submitted_at
     or new.approved_at is distinct from old.approved_at
     or new.paid_at is distinct from old.paid_at
     or new.payment_reference is distinct from old.payment_reference
     or new.rejection_reason is distinct from old.rejection_reason
     or new.extracted_name is distinct from old.extracted_name
     or new.extracted_order_id is distinct from old.extracted_order_id
     or new.extracted_phone is distinct from old.extracted_phone
     or new.extracted_product_name is distinct from old.extracted_product_name
  then
    raise exception 'only admins may modify administrative order fields' using errcode = '42501';
  end if;

  if new.status is distinct from old.status then
    if not (
      (old.status = 'claimed' and new.status = 'order_submitted')
      or (old.status = 'order_confirmed' and new.status = 'review_submitted')
    ) then
      raise exception 'illegal order status transition: % -> %', old.status, new.status
        using errcode = '42501';
    end if;
  end if;

  return new;
end;
$$;

drop trigger if exists orders_guard_before_update on public.orders;
create trigger orders_guard_before_update
  before update on public.orders
  for each row execute function public.enforce_order_update_guard();

-- -----------------------------------------------------------------------------
-- Guard: privilege escalation on profiles.
-- -----------------------------------------------------------------------------
create or replace function public.prevent_profile_escalation()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if auth.uid() is null or public.is_admin(auth.uid()) then
    return new;
  end if;

  if tg_op = 'INSERT' then
    new.role := 'user';
    new.phone_verified := false;
    return new;
  end if;

  if new.role is distinct from old.role then
    raise exception 'only admins may change profiles.role' using errcode = '42501';
  end if;
  if new.phone_verified is distinct from old.phone_verified then
    raise exception 'phone_verified is managed by the server' using errcode = '42501';
  end if;

  new.id := old.id;
  return new;
end;
$$;

drop trigger if exists profiles_guard_before_write on public.profiles;
create trigger profiles_guard_before_write
  before insert or update on public.profiles
  for each row execute function public.prevent_profile_escalation();

-- -----------------------------------------------------------------------------
-- Status timestamps are derived from the status change, never trusted from the
-- client. Name sorts after the guard so the guard sees the requested values.
-- -----------------------------------------------------------------------------
create or replace function public.set_order_status_timestamps()
returns trigger
language plpgsql
as $$
begin
  if new.status is distinct from old.status then
    if new.status = 'order_confirmed' then
      new.order_confirmed_at := now();
    elsif new.status = 'review_submitted' then
      new.review_submitted_at := now();
    elsif new.status = 'approved' then
      new.approved_at := now();
    elsif new.status = 'paid' then
      new.paid_at := now();
    end if;
  end if;
  new.updated_at := now();
  return new;
end;
$$;

drop trigger if exists orders_timestamps_before_update on public.orders;
create trigger orders_timestamps_before_update
  before update on public.orders
  for each row execute function public.set_order_status_timestamps();

-- =============================================================================
-- Admin mutations. Status change + audit_log + notification in one transaction.
-- =============================================================================

create or replace function public.admin_transition_order(
  p_order_id uuid,
  p_new_status text,
  p_action text,
  p_reason text default null,
  p_details jsonb default '{}'::jsonb
)
returns public.orders
language plpgsql
security definer
set search_path = public
as $$
declare
  v_admin uuid := public.assert_admin();
  v_order public.orders;
  v_previous_status text;
  v_product_name text;
  v_message text;
  v_type text;
begin
  select * into v_order from public.orders where id = p_order_id for update;
  if not found then
    raise exception 'order not found' using errcode = 'P0002';
  end if;

  v_previous_status := v_order.status;

  if not (
    (v_previous_status = 'order_submitted' and p_new_status in ('order_confirmed', 'rejected'))
    or (v_previous_status = 'review_submitted' and p_new_status in ('approved', 'rejected'))
  ) then
    raise exception 'illegal admin transition: % -> %', v_previous_status, p_new_status
      using errcode = 'P0001';
  end if;

  if p_new_status = 'rejected' and length(btrim(coalesce(p_reason, ''))) = 0 then
    raise exception 'rejection_reason is required' using errcode = 'P0001';
  end if;

  select p.name into v_product_name from public.products p where p.id = v_order.product_id;

  update public.orders
     set status = p_new_status,
         rejection_reason = case when p_new_status = 'rejected' then btrim(p_reason) else null end
   where id = p_order_id
   returning * into v_order;

  insert into public.audit_log (admin_id, action, target_table, target_id, details)
  values (
    v_admin,
    p_action,
    'orders',
    p_order_id,
    coalesce(p_details, '{}'::jsonb) || jsonb_build_object(
      'from_status', v_previous_status,
      'to_status', p_new_status,
      'rejection_reason', case when p_new_status = 'rejected' then btrim(p_reason) else null end
    )
  );

  v_type := case
    when p_new_status = 'order_confirmed' then 'order_confirmed'
    when p_new_status = 'approved' then 'review_approved'
    else 'order_rejected'
  end;

  v_message := case
    when p_new_status = 'order_confirmed' then
      format('Your order for %s was confirmed. Submit your review to get paid.', coalesce(v_product_name, 'your product'))
    when p_new_status = 'approved' then
      format('Your review for %s was approved. Payment is being processed.', coalesce(v_product_name, 'your product'))
    else
      format('Your submission for %s was rejected: %s', coalesce(v_product_name, 'your product'), btrim(p_reason))
  end;

  insert into public.notifications (user_id, type, message, related_order_id)
  values (v_order.user_id, v_type, v_message, v_order.id);

  return v_order;
end;
$$;

create or replace function public.admin_mark_paid(
  p_order_id uuid,
  p_payment_reference text,
  p_details jsonb default '{}'::jsonb
)
returns public.orders
language plpgsql
security definer
set search_path = public
as $$
declare
  v_admin uuid := public.assert_admin();
  v_order public.orders;
  v_product_name text;
  v_reference text := btrim(coalesce(p_payment_reference, ''));
begin
  if length(v_reference) = 0 then
    raise exception 'payment_reference is required' using errcode = 'P0001';
  end if;
  if length(v_reference) > 120 then
    raise exception 'payment_reference is too long' using errcode = 'P0001';
  end if;

  select * into v_order from public.orders where id = p_order_id for update;
  if not found then
    raise exception 'order not found' using errcode = 'P0002';
  end if;
  if v_order.status <> 'approved' then
    raise exception 'only approved orders can be marked paid (current: %)', v_order.status
      using errcode = 'P0001';
  end if;

  update public.orders
     set status = 'paid', payment_reference = v_reference
   where id = p_order_id
   returning * into v_order;

  insert into public.audit_log (admin_id, action, target_table, target_id, details)
  values (
    v_admin,
    'mark_paid',
    'orders',
    p_order_id,
    coalesce(p_details, '{}'::jsonb) || jsonb_build_object(
      'payment_reference', v_reference,
      'from_status', 'approved',
      'to_status', 'paid'
    )
  );

  select p.name into v_product_name from public.products p where p.id = v_order.product_id;

  insert into public.notifications (user_id, type, message, related_order_id)
  values (
    v_order.user_id,
    'payment_sent',
    format('Payment sent for %s. Reference: %s', coalesce(v_product_name, 'your order'), v_reference),
    v_order.id
  );

  return v_order;
end;
$$;

create or replace function public.admin_create_product(
  p_name text,
  p_brand text default null,
  p_description text default null,
  p_image_url text default null,
  p_total_slots int default 1,
  p_cashback_amount numeric default null
)
returns public.products
language plpgsql
security definer
set search_path = public
as $$
declare
  v_admin uuid := public.assert_admin();
  v_product public.products;
begin
  if length(btrim(coalesce(p_name, ''))) = 0 then
    raise exception 'product name is required' using errcode = 'P0001';
  end if;
  if p_total_slots is null or p_total_slots < 1 or p_total_slots > 100000 then
    raise exception 'total_slots must be between 1 and 100000' using errcode = 'P0001';
  end if;
  if p_cashback_amount is not null and p_cashback_amount < 0 then
    raise exception 'cashback_amount cannot be negative' using errcode = 'P0001';
  end if;

  insert into public.products (name, brand, description, image_url, total_slots, cashback_amount, status, created_by)
  values (
    btrim(p_name),
    nullif(btrim(coalesce(p_brand, '')), ''),
    nullif(btrim(coalesce(p_description, '')), ''),
    nullif(btrim(coalesce(p_image_url, '')), ''),
    p_total_slots,
    p_cashback_amount,
    'open',
    v_admin
  )
  returning * into v_product;

  insert into public.audit_log (admin_id, action, target_table, target_id, details)
  values (
    v_admin,
    'create_product',
    'products',
    v_product.id,
    jsonb_build_object(
      'name', v_product.name,
      'total_slots', v_product.total_slots,
      'cashback_amount', v_product.cashback_amount
    )
  );

  return v_product;
end;
$$;

create or replace function public.admin_update_product(
  p_product_id uuid,
  p_name text default null,
  p_brand text default null,
  p_description text default null,
  p_image_url text default null,
  p_total_slots int default null,
  p_cashback_amount numeric default null,
  p_status text default null
)
returns public.products
language plpgsql
security definer
set search_path = public
as $$
declare
  v_admin uuid := public.assert_admin();
  v_product public.products;
  v_before public.products;
begin
  select * into v_before from public.products where id = p_product_id for update;
  if not found then
    raise exception 'product not found' using errcode = 'P0002';
  end if;

  if p_status is not null and p_status not in ('open', 'closed') then
    raise exception 'invalid product status' using errcode = 'P0001';
  end if;
  if p_name is not null and length(btrim(p_name)) = 0 then
    raise exception 'product name cannot be empty' using errcode = 'P0001';
  end if;
  if p_total_slots is not null and (p_total_slots < 1 or p_total_slots > 100000) then
    raise exception 'total_slots must be between 1 and 100000' using errcode = 'P0001';
  end if;
  if p_total_slots is not null and p_total_slots < v_before.slots_filled then
    raise exception 'total_slots cannot be lower than the % slots already filled', v_before.slots_filled
      using errcode = 'P0001';
  end if;
  if p_cashback_amount is not null and p_cashback_amount < 0 then
    raise exception 'cashback_amount cannot be negative' using errcode = 'P0001';
  end if;

  update public.products
     set name = coalesce(nullif(btrim(coalesce(p_name, '')), ''), name),
         brand = case when p_brand is null then brand else nullif(btrim(p_brand), '') end,
         description = case when p_description is null then description else nullif(btrim(p_description), '') end,
         image_url = case when p_image_url is null then image_url else nullif(btrim(p_image_url), '') end,
         total_slots = coalesce(p_total_slots, total_slots),
         cashback_amount = coalesce(p_cashback_amount, cashback_amount),
         status = coalesce(p_status, status)
   where id = p_product_id
   returning * into v_product;

  insert into public.audit_log (admin_id, action, target_table, target_id, details)
  values (
    v_admin,
    case
      when p_status = 'closed' and v_before.status <> 'closed' then 'close_product'
      when p_status = 'open' and v_before.status <> 'open' then 'reopen_product'
      else 'update_product'
    end,
    'products',
    p_product_id,
    jsonb_build_object(
      'before', jsonb_build_object(
        'name', v_before.name, 'brand', v_before.brand, 'total_slots', v_before.total_slots,
        'cashback_amount', v_before.cashback_amount, 'status', v_before.status
      ),
      'after', jsonb_build_object(
        'name', v_product.name, 'brand', v_product.brand, 'total_slots', v_product.total_slots,
        'cashback_amount', v_product.cashback_amount, 'status', v_product.status
      )
    )
  );

  return v_product;
end;
$$;

create or replace function public.admin_log_bank_reveal(
  p_user_id uuid,
  p_order_id uuid default null,
  p_context text default 'payments_console'
)
returns uuid
language plpgsql
security definer
set search_path = public
as $$
declare
  v_admin uuid := public.assert_admin();
  v_id uuid;
begin
  insert into public.audit_log (admin_id, action, target_table, target_id, details)
  values (
    v_admin,
    'reveal_bank_account',
    'bank_details',
    p_user_id,
    jsonb_build_object('context', p_context, 'order_id', p_order_id)
  )
  returning id into v_id;
  return v_id;
end;
$$;

-- -----------------------------------------------------------------------------
-- Execution rights: admin functions are for signed-in users only (they
-- self-check the role) and never for the anonymous role.
-- -----------------------------------------------------------------------------
revoke all on function public.assert_admin() from public;
revoke all on function public.claim_product_slot(uuid) from public;
revoke all on function public.admin_transition_order(uuid, text, text, text, jsonb) from public;
revoke all on function public.admin_mark_paid(uuid, text, jsonb) from public;
revoke all on function public.admin_create_product(text, text, text, text, int, numeric) from public;
revoke all on function public.admin_update_product(uuid, text, text, text, text, int, numeric, text) from public;
revoke all on function public.admin_log_bank_reveal(uuid, uuid, text) from public;

-- Supabase grants EXECUTE to anon by default, so revoke it explicitly. The
-- admin_* functions re-check the caller anyway (assert_admin); this just keeps
-- anonymous requests from reaching them at all.
revoke execute on function public.claim_product_slot(uuid) from anon;
revoke execute on function public.admin_transition_order(uuid, text, text, text, jsonb) from anon;
revoke execute on function public.admin_mark_paid(uuid, text, jsonb) from anon;
revoke execute on function public.admin_create_product(text, text, text, text, int, numeric) from anon;
revoke execute on function public.admin_update_product(uuid, text, text, text, text, int, numeric, text) from anon;
revoke execute on function public.admin_log_bank_reveal(uuid, uuid, text) from anon;
revoke execute on function public.is_admin(uuid) from anon;

grant execute on function public.assert_admin() to authenticated, service_role;
grant execute on function public.claim_product_slot(uuid) to authenticated;
grant execute on function public.admin_transition_order(uuid, text, text, text, jsonb) to authenticated;
grant execute on function public.admin_mark_paid(uuid, text, jsonb) to authenticated;
grant execute on function public.admin_create_product(text, text, text, text, int, numeric) to authenticated;
grant execute on function public.admin_update_product(uuid, text, text, text, text, int, numeric, text) to authenticated;
grant execute on function public.admin_log_bank_reveal(uuid, uuid, text) to authenticated;


-- ----------------------------------------------------------------------------
-- >>> 0004_storage.sql
-- ----------------------------------------------------------------------------
-- =============================================================================
-- 0004  Private storage buckets + policies.
--
-- Both buckets are PRIVATE. Nothing is served from a permanent public URL; the
-- app hands out short-lived signed URLs (see src/lib/storage.ts).
-- file_size_limit / allowed_mime_types are enforced by Storage itself, in
-- addition to the server-side validation in the upload route.
-- =============================================================================

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values (
  'screenshots',
  'screenshots',
  false,
  5242880, -- 5 MB
  array['image/png','image/jpeg','image/webp','image/heic','image/heif']
)
on conflict (id) do update
  set public = false,
      file_size_limit = excluded.file_size_limit,
      allowed_mime_types = excluded.allowed_mime_types;

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values (
  'product-images',
  'product-images',
  false,
  5242880, -- 5 MB
  array['image/png','image/jpeg','image/webp','image/heic','image/heif']
)
on conflict (id) do update
  set public = false,
      file_size_limit = excluded.file_size_limit,
      allowed_mime_types = excluded.allowed_mime_types;

drop policy if exists screenshots_admin_all on storage.objects;
drop policy if exists screenshots_owner_insert on storage.objects;
drop policy if exists screenshots_owner_select on storage.objects;
drop policy if exists product_images_admin_all on storage.objects;
drop policy if exists product_images_read on storage.objects;

-- Screenshots: admins manage everything; a user may only write into a folder
-- named after their own auth uid and only read that same folder.
create policy screenshots_admin_all on storage.objects
  for all to authenticated
  using (bucket_id = 'screenshots' and public.is_admin())
  with check (bucket_id = 'screenshots' and public.is_admin());

create policy screenshots_owner_insert on storage.objects
  for insert to authenticated
  with check (
    bucket_id = 'screenshots'
    and (storage.foldername(name))[1] = auth.uid()::text
  );

create policy screenshots_owner_select on storage.objects
  for select to authenticated
  using (
    bucket_id = 'screenshots'
    and ((storage.foldername(name))[1] = auth.uid()::text or public.is_admin())
  );

-- Product images: admins manage; any signed-in user may read (product catalogue).
create policy product_images_admin_all on storage.objects
  for all to authenticated
  using (bucket_id = 'product-images' and public.is_admin())
  with check (bucket_id = 'product-images' and public.is_admin());

create policy product_images_read on storage.objects
  for select to authenticated
  using (bucket_id = 'product-images');


-- ----------------------------------------------------------------------------
-- >>> 0005_bootstrap_admin.sql
-- ----------------------------------------------------------------------------
-- =============================================================================
-- 0005  Admin bootstrapping.
--
-- There is no public admin sign-up. Admin accounts are created out of band:
--   * create the auth user   ->  node scripts/create-admin.mjs  (service role)
--   * promote it to admin    ->  select public.promote_admin('admin@example.com');
-- promote_admin is intentionally NOT executable by anon or authenticated.
-- =============================================================================

create or replace function public.promote_admin(p_email text)
returns uuid
language plpgsql
security definer
set search_path = public
as $$
declare
  v_user_id uuid;
begin
  select id into v_user_id from auth.users where lower(email) = lower(btrim(p_email));
  if v_user_id is null then
    raise exception 'no auth user with email %', p_email using errcode = 'P0002';
  end if;

  insert into public.profiles (id, full_name, role)
  values (v_user_id, split_part(p_email, '@', 1), 'admin')
  on conflict (id) do update set role = 'admin';

  return v_user_id;
end;
$$;

revoke all on function public.promote_admin(text) from public;
revoke all on function public.promote_admin(text) from anon, authenticated;
grant execute on function public.promote_admin(text) to service_role;


-- ----------------------------------------------------------------------------
-- >>> 0006_user_panel.sql
-- ----------------------------------------------------------------------------
-- =============================================================================
-- 0006  User panel support.
--
-- Adds only what the user-facing panel needs. Nothing in 0001-0005 is edited:
-- the one existing function that had to change (the orders guard) is replaced
-- with `create or replace`, which is the migration-safe way to do it.
--
-- New objects
--   * public.phone_verifications  - hashed OTP codes, unreachable by any client
--   * public.rate_limits          - persistent rate limiting (replaces the
--                                   per-isolate in-memory window in production)
--   * consume_rate_limit()        - atomic fixed-window counter
--   * verify_phone_code()         - atomic OTP check + consume + flip the flag
--   * claim_product_for_user()    - verified-only claim, reuses claim_product_slot
--   * submit_order_proof()        - ownership + verified checks, then submit
--   * submit_review_proof()       - same, for the review stage
--   * user_save_bank_details()    - encrypt-at-rest write + audit row as the user
--   * realtime publication entries for products / orders / notifications
-- =============================================================================

-- -----------------------------------------------------------------------------
-- OTP codes.
--
-- RLS is enabled with NO policies and no grants to anon/authenticated, so a
-- client session cannot read, insert or brute-force this table even with the
-- anon key. Only service_role (server-side routes) can touch it, and even then
-- only a SHA-256 hash of the code is stored - never the code itself.
-- -----------------------------------------------------------------------------
create table if not exists public.phone_verifications (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null
    constraint phone_verifications_user_id_fkey references public.profiles(id) on delete cascade,
  phone text not null,
  code_hash text not null,
  attempts int not null default 0,
  max_attempts int not null default 5,
  expires_at timestamptz not null,
  consumed_at timestamptz,
  created_at timestamptz not null default now()
);

create index if not exists phone_verifications_user_idx
  on public.phone_verifications (user_id, created_at desc);
create index if not exists phone_verifications_live_idx
  on public.phone_verifications (user_id)
  where consumed_at is null;

alter table public.phone_verifications enable row level security;

revoke all on public.phone_verifications from anon, authenticated;
grant all on public.phone_verifications to service_role;

comment on table public.phone_verifications is
  'One-time phone codes. Stores a hash only; no client role can read this table.';

-- -----------------------------------------------------------------------------
-- Persistent rate limiting.
--
-- Phase 1 fell back to a per-isolate in-memory window when Upstash was not
-- configured, which does not hold across Cloudflare isolates. This table makes
-- the limiter durable with no extra vendor, and the function is atomic so
-- concurrent requests cannot both slip past the last allowed attempt.
-- -----------------------------------------------------------------------------
create table if not exists public.rate_limits (
  key text primary key,
  count int not null default 0,
  window_started_at timestamptz not null default now(),
  expires_at timestamptz not null
);

create index if not exists rate_limits_expires_idx on public.rate_limits (expires_at);

alter table public.rate_limits enable row level security;

revoke all on public.rate_limits from anon, authenticated;
grant all on public.rate_limits to service_role;

create or replace function public.consume_rate_limit(
  p_key text,
  p_limit int,
  p_window_ms int
)
returns table (allowed boolean, remaining int, retry_after_seconds int)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_now timestamptz := clock_timestamp();
  v_row public.rate_limits;
  v_seconds double precision := greatest(p_window_ms, 1)::double precision / 1000.0;
begin
  if p_key is null or length(p_key) = 0 or length(p_key) > 400 then
    raise exception 'invalid rate limit key' using errcode = 'P0001';
  end if;
  if p_limit < 1 or p_window_ms < 1 then
    raise exception 'invalid rate limit arguments' using errcode = 'P0001';
  end if;

  -- Single statement: the row lock serialises concurrent callers.
  insert into public.rate_limits as rl (key, count, window_started_at, expires_at)
  values (p_key, 1, v_now, v_now + make_interval(secs => v_seconds))
  on conflict (key) do update
    set count = case when rl.expires_at <= v_now then 1 else rl.count + 1 end,
        window_started_at = case when rl.expires_at <= v_now then v_now else rl.window_started_at end,
        expires_at = case
          when rl.expires_at <= v_now then v_now + make_interval(secs => v_seconds)
          else rl.expires_at
        end
  returning * into v_row;

  allowed := v_row.count <= p_limit;
  remaining := greatest(0, p_limit - v_row.count);
  retry_after_seconds := case
    when v_row.count <= p_limit then 0
    else greatest(1, ceil(extract(epoch from (v_row.expires_at - v_now))))::int
  end;
  return next;
end;
$$;

comment on function public.consume_rate_limit(text, int, int) is
  'Atomic fixed-window counter used by the app rate limiter. service_role only.';

revoke all on function public.consume_rate_limit(text, int, int) from public;
-- Supabase grants EXECUTE on a new function to anon/authenticated by default, so
-- revoke ... from public alone is NOT enough. Without this line any anonymous
-- caller holding the anon key could reach a SECURITY DEFINER function that has no
-- admin check of its own.
revoke execute on function public.consume_rate_limit(text, int, int) from anon, authenticated;
grant execute on function public.consume_rate_limit(text, int, int) to service_role;

-- -----------------------------------------------------------------------------
-- Realtime: the live slot counter and the live order tracker subscribe to these
-- tables from the browser with the anon key, so every message is still filtered
-- by the RLS policies in 0002. Guarded so re-running the migration is a no-op.
-- -----------------------------------------------------------------------------
do $$
declare
  t text;
begin
  if exists (select 1 from pg_publication where pubname = 'supabase_realtime') then
    foreach t in array array['products', 'orders', 'notifications'] loop
      if not exists (
        select 1 from pg_publication_tables
        where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = t
      ) then
        execute format('alter publication supabase_realtime add table public.%I', t);
      end if;
    end loop;
  end if;
end;
$$;

-- -----------------------------------------------------------------------------
-- Orders guard, extended for the user panel.
--
-- Phase 1 blocked a non-admin from touching the extracted_* columns at all.
-- The user confirm screen is exactly where those values get corrected, so the
-- owner may now write them - but only while the order is still an unsubmitted
-- 'claimed' row. Everything genuinely administrative stays admin-only, and the
-- proof columns freeze once the matching stage has been submitted.
-- -----------------------------------------------------------------------------
create or replace function public.enforce_order_update_guard()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  -- No JWT in the request context means service_role / server-side code.
  if auth.uid() is null or public.is_admin(auth.uid()) then
    return new;
  end if;

  if new.user_id is distinct from old.user_id then
    raise exception 'orders.user_id is immutable' using errcode = '42501';
  end if;
  if new.product_id is distinct from old.product_id then
    raise exception 'orders.product_id is immutable' using errcode = '42501';
  end if;

  -- Admin-only for the whole lifetime of the row.
  if new.order_confirmed_at is distinct from old.order_confirmed_at
     or new.review_submitted_at is distinct from old.review_submitted_at
     or new.approved_at is distinct from old.approved_at
     or new.paid_at is distinct from old.paid_at
     or new.payment_reference is distinct from old.payment_reference
     or new.rejection_reason is distinct from old.rejection_reason
  then
    raise exception 'only admins may modify administrative order fields' using errcode = '42501';
  end if;

  -- Owner-editable only while the claim is still unsubmitted.
  if old.status <> 'claimed' and (
       new.extracted_name is distinct from old.extracted_name
    or new.extracted_order_id is distinct from old.extracted_order_id
    or new.extracted_phone is distinct from old.extracted_phone
    or new.extracted_product_name is distinct from old.extracted_product_name
    or new.order_screenshot_url is distinct from old.order_screenshot_url
  ) then
    raise exception 'order proof is locked once the order has been submitted'
      using errcode = '42501';
  end if;

  -- Review proof is editable only while the review is still owed.
  if old.status not in ('order_confirmed', 'review_pending') and (
       new.review_screenshot_url is distinct from old.review_screenshot_url
    or new.review_link is distinct from old.review_link
  ) then
    raise exception 'review proof is locked once the review has been submitted'
      using errcode = '42501';
  end if;

  if new.status is distinct from old.status then
    if not (
      (old.status = 'claimed' and new.status = 'order_submitted')
      or (old.status = 'order_confirmed' and new.status = 'review_submitted')
      or (old.status = 'review_pending' and new.status = 'review_submitted')
    ) then
      raise exception 'illegal order status transition: % -> %', old.status, new.status
        using errcode = '42501';
    end if;

    -- Submitting an order proof is only meaningful once the user has confirmed
    -- what the extraction read.
    if old.status = 'claimed' and new.status = 'order_submitted' and new.user_confirmed is not true then
      raise exception 'confirm the order details before submitting' using errcode = '42501';
    end if;

    -- A review submission needs at least one form of proof.
    if old.status in ('order_confirmed', 'review_pending')
       and new.status = 'review_submitted'
       and coalesce(new.review_screenshot_url, new.review_link) is null
    then
      raise exception 'attach a review screenshot or paste the review link'
        using errcode = '42501';
    end if;
  end if;

  return new;
end;
$$;

-- -----------------------------------------------------------------------------
-- assert_verified_user: the user-panel counterpart of assert_admin().
--
-- Requirement: an unverified phone must not be able to claim or submit. This is
-- enforced here in the database, not merely by hiding a button, so a crafted
-- RPC call from a client is rejected too.
-- -----------------------------------------------------------------------------
create or replace function public.assert_verified_user()
returns uuid
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_user uuid := auth.uid();
begin
  if v_user is null then
    raise exception 'authentication required'
      using errcode = '42501', hint = 'auth_required';
  end if;
  if not exists (select 1 from public.profiles p where p.id = v_user and p.phone_verified) then
    raise exception 'verify your phone number to continue'
      using errcode = '42501', hint = 'phone_unverified';
  end if;
  return v_user;
end;
$$;

comment on function public.assert_verified_user() is
  'Returns auth.uid() for a signed-in user whose phone is verified, else raises.';

-- -----------------------------------------------------------------------------
-- verify_phone_code: consume an OTP atomically.
--
-- Returns a status word rather than raising, so the route can answer precisely
-- without leaking whether a code existed. Attempt accounting, expiry and the
-- single-use mark all happen under one row lock, so a burst of guesses cannot
-- race past max_attempts.
--
-- SECURITY DEFINER + service_role only: it flips profiles.phone_verified, which
-- the profiles guard trigger forbids for any client session.
-- -----------------------------------------------------------------------------
create or replace function public.verify_phone_code(p_user_id uuid, p_code_hash text)
returns text
language plpgsql
security definer
set search_path = public
as $$
declare
  v_row public.phone_verifications;
  v_phone text;
begin
  if p_user_id is null or p_code_hash is null or length(p_code_hash) = 0 then
    return 'invalid';
  end if;

  select p.phone into v_phone from public.profiles p where p.id = p_user_id;
  if v_phone is null or length(btrim(v_phone)) = 0 then
    return 'no_phone';
  end if;

  select * into v_row
    from public.phone_verifications
   where user_id = p_user_id and consumed_at is null
   order by created_at desc
   limit 1
   for update;

  if not found then
    return 'missing';
  end if;

  if v_row.expires_at <= now() then
    update public.phone_verifications set consumed_at = now() where id = v_row.id;
    return 'expired';
  end if;

  if v_row.attempts >= v_row.max_attempts then
    update public.phone_verifications set consumed_at = now() where id = v_row.id;
    return 'too_many_attempts';
  end if;

  update public.phone_verifications set attempts = attempts + 1 where id = v_row.id;

  -- The code must also belong to the number currently on the profile, so an OTP
  -- issued before a phone change cannot be replayed afterwards.
  if v_row.phone is distinct from v_phone or v_row.code_hash <> p_code_hash then
    return 'invalid';
  end if;

  update public.phone_verifications set consumed_at = now() where id = v_row.id;
  update public.profiles set phone_verified = true where id = p_user_id;
  return 'verified';
end;
$$;

revoke all on function public.verify_phone_code(uuid, text) from public;
-- Supabase grants EXECUTE on a new function to anon/authenticated by default, so
-- revoke ... from public alone is NOT enough. Without this line any anonymous
-- caller holding the anon key could reach a SECURITY DEFINER function that has no
-- admin check of its own.
revoke execute on function public.verify_phone_code(uuid, text) from anon, authenticated;
grant execute on function public.verify_phone_code(uuid, text) to service_role;

-- -----------------------------------------------------------------------------
-- claim_product_for_user: atomically consume a slot AND create the order.
--
-- Reuses the Phase 1 claim_product_slot() so there is exactly one atomic claim
-- implementation. Both statements run in one transaction: if the order insert
-- fails (for example the user already holds an active claim on this product),
-- the slot increment is rolled back with it.
--
-- Returns NULL when the slot could not be taken (sold out, closed or unknown).
-- -----------------------------------------------------------------------------
create or replace function public.claim_product_for_user(p_product_id uuid)
returns public.orders
language plpgsql
security definer
set search_path = public
as $$
declare
  v_user uuid := public.assert_verified_user();
  v_claimed boolean;
  v_order public.orders;
begin
  v_claimed := public.claim_product_slot(p_product_id);
  if not v_claimed then
    return null;
  end if;

  begin
    insert into public.orders (user_id, product_id, status)
    values (v_user, p_product_id, 'claimed')
    returning * into v_order;
  exception
    when unique_violation then
      raise exception 'you already hold an active claim on this product'
        using errcode = 'P0001', hint = 'duplicate_claim';
    when foreign_key_violation then
      raise exception 'that product does not exist'
        using errcode = 'P0002', hint = 'product_not_found';
  end;

  return v_order;
end;
$$;

revoke all on function public.claim_product_for_user(uuid) from public;
revoke execute on function public.claim_product_for_user(uuid) from anon;
grant execute on function public.claim_product_for_user(uuid) to authenticated;

-- -----------------------------------------------------------------------------
-- submit_order_proof
--
-- Ownership, verification state, review state and the storage path are all
-- re-checked here. The path must sit inside the caller's own storage folder, so
-- a user cannot point their order at somebody else's screenshot. The extracted
-- values arrive from the confirm screen - the user's correction is authoritative.
-- -----------------------------------------------------------------------------
create or replace function public.submit_order_proof(
  p_order_id uuid,
  p_screenshot_path text,
  p_name text default null,
  p_order_ref text default null,
  p_phone text default null,
  p_product_name text default null
)
returns public.orders
language plpgsql
security definer
set search_path = public
as $$
declare
  v_user uuid := public.assert_verified_user();
  v_order public.orders;
  v_path text := btrim(coalesce(p_screenshot_path, ''));
  v_name text := nullif(btrim(coalesce(p_name, '')), '');
  v_ref text := nullif(btrim(coalesce(p_order_ref, '')), '');
  v_phone text := nullif(btrim(coalesce(p_phone, '')), '');
  v_product text := nullif(btrim(coalesce(p_product_name, '')), '');
begin
  select * into v_order
    from public.orders
   where id = p_order_id and user_id = v_user
   for update;

  if not found then
    raise exception 'order not found' using errcode = 'P0002', hint = 'order_not_found';
  end if;

  if v_order.status <> 'claimed' then
    raise exception 'this order has already been submitted'
      using errcode = 'P0001', hint = 'order_locked';
  end if;

  if length(v_path) = 0 or v_path not like v_user::text || '/%' then
    raise exception 'invalid screenshot path' using errcode = '42501', hint = 'invalid_path';
  end if;

  if v_ref is null or length(v_ref) < 3 then
    raise exception 'the order id from the screenshot is required'
      using errcode = 'P0001', hint = 'order_ref_required';
  end if;

  if length(v_path) > 1024
     or (v_name is not null and length(v_name) > 200)
     or length(v_ref) > 200
     or (v_phone is not null and (length(v_phone) > 40 or v_phone !~ '^[0-9+][0-9+ -]{4,39}$'))
     or (v_product is not null and length(v_product) > 300)
  then
    raise exception 'one of the submitted fields is not valid'
      using errcode = 'P0001', hint = 'invalid_field';
  end if;

  update public.orders
     set order_screenshot_url = v_path,
         extracted_name = v_name,
         extracted_order_id = v_ref,
         extracted_phone = v_phone,
         extracted_product_name = v_product,
         user_confirmed = true,
         status = 'order_submitted'
   where id = p_order_id
   returning * into v_order;

  return v_order;
end;
$$;

revoke all on function public.submit_order_proof(uuid, text, text, text, text, text) from public;
revoke execute on function public.submit_order_proof(uuid, text, text, text, text, text) from anon;
grant execute on function public.submit_order_proof(uuid, text, text, text, text, text) to authenticated;

-- -----------------------------------------------------------------------------
-- submit_review_proof
--
-- At least one of screenshot / live review link is required, exactly as the
-- spec asks. review_submitted_at is filled by the existing timestamp trigger,
-- not by the caller.
-- -----------------------------------------------------------------------------
create or replace function public.submit_review_proof(
  p_order_id uuid,
  p_screenshot_path text default null,
  p_review_link text default null
)
returns public.orders
language plpgsql
security definer
set search_path = public
as $$
declare
  v_user uuid := public.assert_verified_user();
  v_order public.orders;
  v_path text := nullif(btrim(coalesce(p_screenshot_path, '')), '');
  v_link text := nullif(btrim(coalesce(p_review_link, '')), '');
begin
  select * into v_order
    from public.orders
   where id = p_order_id and user_id = v_user
   for update;

  if not found then
    raise exception 'order not found' using errcode = 'P0002', hint = 'order_not_found';
  end if;

  if v_order.status not in ('order_confirmed', 'review_pending') then
    raise exception 'this order is not waiting for a review'
      using errcode = 'P0001', hint = 'order_locked';
  end if;

  if v_path is null and v_link is null then
    raise exception 'attach a review screenshot or paste the review link'
      using errcode = 'P0001', hint = 'proof_required';
  end if;

  if v_path is not null and (length(v_path) > 1024 or v_path not like v_user::text || '/%') then
    raise exception 'invalid screenshot path' using errcode = '42501', hint = 'invalid_path';
  end if;

  if v_link is not null and (length(v_link) > 1024 or v_link !~* '^https?://[^[:space:]]+$') then
    raise exception 'the review link must be a full http(s) url'
      using errcode = 'P0001', hint = 'invalid_link';
  end if;

  update public.orders
     set review_screenshot_url = v_path,
         review_link = v_link,
         status = 'review_submitted'
   where id = p_order_id
   returning * into v_order;

  return v_order;
end;
$$;

revoke all on function public.submit_review_proof(uuid, text, text) from public;
revoke execute on function public.submit_review_proof(uuid, text, text) from anon;
grant execute on function public.submit_review_proof(uuid, text, text) to authenticated;

-- -----------------------------------------------------------------------------
-- user_save_bank_details
--
-- Encryption itself happens in the app layer (src/lib/crypto.ts) - there is no
-- second crypto implementation here. This function only stores the ciphertext,
-- records the change against the *user* in audit_log, and returns the masked
-- projection.
--
-- The return type is deliberately a narrow table rather than public.bank_details:
-- returning the row type would echo account_number_encrypted back through
-- PostgREST, which the spec forbids.
--
-- Blank fields keep their stored value, so a user can update their holder name
-- or UPI without re-typing the account number.
-- -----------------------------------------------------------------------------
create or replace function public.user_save_bank_details(
  p_account_holder_name text default null,
  p_account_number_encrypted text default null,
  p_account_number_last4 text default null,
  p_ifsc_code text default null,
  p_upi_id text default null
)
returns table (
  user_id uuid,
  account_holder_name text,
  account_number_last4 text,
  ifsc_code text,
  upi_id text,
  updated_at timestamptz
)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_user uuid := auth.uid();
  v_prev public.bank_details;
  v_existed boolean;
  v_holder text;
  v_req_enc text;
  v_req_last4 text;
  v_ifsc text;
  v_upi text;
  v_enc text;
  v_last4 text;
  v_changed boolean;
begin
  if v_user is null then
    raise exception 'authentication required' using errcode = '42501', hint = 'auth_required';
  end if;

  -- Qualified deliberately: the RETURNS TABLE output column is also called
  -- user_id, and an unqualified reference is ambiguous to the planner.
  select * into v_prev from public.bank_details b where b.user_id = v_user;
  v_existed := found;

  v_holder := nullif(btrim(coalesce(p_account_holder_name, '')), '');
  v_req_enc := nullif(btrim(coalesce(p_account_number_encrypted, '')), '');
  v_req_last4 := nullif(btrim(coalesce(p_account_number_last4, '')), '');
  v_ifsc := upper(nullif(btrim(coalesce(p_ifsc_code, '')), ''));
  v_upi := nullif(btrim(coalesce(p_upi_id, '')), '');

  -- Resolve "blank means keep what is stored".
  v_enc := coalesce(v_req_enc, v_prev.account_number_encrypted);
  v_last4 := coalesce(v_req_last4, v_prev.account_number_last4);
  v_ifsc := coalesce(v_ifsc, v_prev.ifsc_code);
  v_upi := coalesce(v_upi, v_prev.upi_id);
  v_holder := coalesce(v_holder, v_prev.account_holder_name);

  if v_enc is null and v_upi is null then
    raise exception 'provide a bank account or a UPI id'
      using errcode = 'P0001', hint = 'payout_required';
  end if;

  if v_req_enc is not null then
    if v_req_last4 is null or v_req_last4 !~ '^[0-9]{4}$' then
      raise exception 'the last four digits of the account number are required'
        using errcode = 'P0001', hint = 'invalid_last4';
    end if;
    if length(v_req_enc) > 2048 or v_req_enc !~ '^v1\.[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+$' then
      raise exception 'the account number was not encrypted correctly'
        using errcode = 'P0001', hint = 'invalid_ciphertext';
    end if;
  end if;

  if v_enc is not null and v_ifsc is not null and v_ifsc !~ '^[A-Z]{4}0[A-Z0-9]{6}$' then
    raise exception 'enter a valid IFSC code' using errcode = 'P0001', hint = 'invalid_ifsc';
  end if;

  if v_req_enc is not null and (v_ifsc is null or v_ifsc !~ '^[A-Z]{4}0[A-Z0-9]{6}$') then
    raise exception 'an IFSC code is required with a bank account number'
      using errcode = 'P0001', hint = 'invalid_ifsc';
  end if;

  if v_upi is not null
     and (length(v_upi) > 256 or v_upi !~ '^[A-Za-z0-9._+-]{2,64}@[A-Za-z][A-Za-z0-9]{1,63}$')
  then
    raise exception 'enter a valid UPI id' using errcode = 'P0001', hint = 'invalid_upi';
  end if;

  if v_holder is not null and length(v_holder) > 120 then
    raise exception 'the account holder name is too long'
      using errcode = 'P0001', hint = 'invalid_field';
  end if;

  v_changed := v_req_enc is not null
    and (not v_existed or v_req_enc is distinct from v_prev.account_number_encrypted);

  insert into public.bank_details (
    user_id, account_holder_name, account_number_encrypted, account_number_last4, ifsc_code, upi_id
  )
  values (v_user, v_holder, v_enc, v_last4, v_ifsc, v_upi)
  -- Named rather than inferred: the RETURNS TABLE column is also user_id, so a
  -- bare `on conflict (user_id)` is ambiguous inside plpgsql.
  on conflict on constraint bank_details_pkey do update
    set account_holder_name = excluded.account_holder_name,
        account_number_encrypted = excluded.account_number_encrypted,
        account_number_last4 = excluded.account_number_last4,
        ifsc_code = excluded.ifsc_code,
        upi_id = excluded.upi_id,
        updated_at = now();

  -- Who changed their payout details, and when. Never the account number.
  insert into public.audit_log (admin_id, action, target_table, target_id, details)
  values (
    v_user,
    case when v_existed then 'update_bank_details' else 'create_bank_details' end,
    'bank_details',
    v_user,
    jsonb_build_object(
      'actor_role', 'user',
      'account_number_changed', v_changed,
      'account_number_last4', v_last4,
      'ifsc_code', v_ifsc,
      'upi_id', v_upi,
      'holder_name', v_holder
    )
  );

  return query
    select b.user_id, b.account_holder_name, b.account_number_last4, b.ifsc_code, b.upi_id, b.updated_at
      from public.bank_details b
     where b.user_id = v_user;
end;
$$;

revoke all on function public.user_save_bank_details(text, text, text, text, text) from public;
revoke execute on function public.user_save_bank_details(text, text, text, text, text) from anon;
grant execute on function public.user_save_bank_details(text, text, text, text, text) to authenticated;

-- -----------------------------------------------------------------------------
-- Execution rights for the user-facing helpers.
-- -----------------------------------------------------------------------------
revoke all on function public.assert_verified_user() from public;
revoke execute on function public.assert_verified_user() from anon;
grant execute on function public.assert_verified_user() to authenticated, service_role;


-- ----------------------------------------------------------------------------
-- >>> 0007_withdraw_claim.sql
-- ----------------------------------------------------------------------------
-- =============================================================================
-- 0007  Withdraw a claim.
--
-- Lets a reviewer back out of a claim they have not acted on yet, and gives the
-- slot straight back to the pool. Nothing in 0001-0006 is edited: this adds one
-- function.
--
--   * withdraw_order_claim(order id)  - release the slot + drop the claim + audit
--
-- Why a delete rather than a new status: a withdrawn claim never reached the
-- team, so there is nothing for anybody to see afterwards. The
-- orders_one_active_per_product index only covers rows that still exist, so
-- deleting frees the reviewer to claim the same product again, which is exactly
-- what "give the slot back" should mean.
--
-- Only a claim that is still 'claimed' can be withdrawn. Once the order
-- screenshot has been submitted an admin is already acting on it, and the row
-- must stay put for them - the same rule the update guard in 0006 enforces.
-- =============================================================================

create or replace function public.withdraw_order_claim(p_order_id uuid)
returns table (
  order_id uuid,
  product_id uuid,
  slots_filled int,
  total_slots int
)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_user uuid := auth.uid();
  v_product_id uuid;
  v_order public.orders;
  v_product public.products;
begin
  if v_user is null then
    raise exception 'authentication required' using errcode = '42501', hint = 'auth_required';
  end if;

  -- Ownership is asserted in the lookup itself, so guessing somebody else's
  -- order id fails here rather than relying on RLS to hide the row.
  select o.product_id into v_product_id
    from public.orders o
   where o.id = p_order_id and o.user_id = v_user;

  if not found then
    raise exception 'order not found' using errcode = 'P0002', hint = 'order_not_found';
  end if;

  -- Lock order matters: the claim path takes the product row and then inserts
  -- the order, so this takes products first and the order second. Two
  -- overlapping withdraws therefore queue on the product lock instead of
  -- deadlocking on each other.
  select * into v_product
    from public.products p
   where p.id = v_product_id
   for update;

  if not found then
    raise exception 'that product no longer exists' using errcode = 'P0002', hint = 'product_not_found';
  end if;

  select * into v_order
    from public.orders o
   where o.id = p_order_id and o.user_id = v_user
   for update;

  if not found then
    raise exception 'order not found' using errcode = 'P0002', hint = 'order_not_found';
  end if;

  -- Re-checked while holding the lock: the reviewer may have submitted the
  -- screenshot a moment ago, in which case the row has to stay for the admin.
  if v_order.status <> 'claimed' then
    raise exception 'this claim has already been submitted and can no longer be withdrawn'
      using errcode = 'P0001', hint = 'order_locked';
  end if;

  -- greatest() is a belt-and-braces guard: the products_slots_bounds CHECK
  -- constraint would refuse a negative count, but a clamp here means a
  -- double-submit can never turn into an error the user has to read.
  -- Every column here is qualified: `slots_filled` is also a RETURNS TABLE
  -- output name, and an unqualified reference is ambiguous to the planner.
  update public.products p
     set slots_filled = greatest(p.slots_filled - 1, 0)
   where p.id = v_product_id
   returning * into v_product;

  -- Defensive: a claim in this state should not have notifications pointing at
  -- it, but notifications.related_order_id has no ON DELETE rule, so clear any
  -- that exist rather than letting the foreign key block the withdrawal.
  delete from public.notifications n where n.related_order_id = p_order_id;

  delete from public.orders o where o.id = p_order_id;

  insert into public.audit_log (admin_id, action, target_table, target_id, details)
  values (
    v_user,
    'withdraw_claim',
    'orders',
    p_order_id,
    jsonb_build_object(
      'actor_role', 'user',
      'product_id', v_product_id,
      'previous_status', v_order.status,
      'slots_filled_after', v_product.slots_filled,
      'total_slots', v_product.total_slots,
      'extracted_order_id', v_order.extracted_order_id,
      'had_screenshot', v_order.order_screenshot_url is not null
    )
  );

  return query select p_order_id, v_product_id, v_product.slots_filled, v_product.total_slots;
end;
$$;

comment on function public.withdraw_order_claim(uuid) is
  'Owner-only: releases a still-unsubmitted claim, returns the slot to the pool and audits the change.';

revoke all on function public.withdraw_order_claim(uuid) from public;
revoke execute on function public.withdraw_order_claim(uuid) from anon, authenticated;
grant execute on function public.withdraw_order_claim(uuid) to authenticated;


-- ----------------------------------------------------------------------------
-- >>> 0008_product_details.sql
-- ----------------------------------------------------------------------------
-- =============================================================================
-- 0008  Product detail fields.
--
-- Records the extra Amazon-facing detail on a product:
--   * product_link  - the Amazon product URL
--   * campaign      - the campaign label the admin files the product under
--   * asin_code     - Amazon's ASIN
--
-- brand_name gets no column: public.products.brand already exists and holds
-- exactly that value, so the form reuses it rather than growing a duplicate.
--
-- admin_create_product and admin_update_product take three new arguments, which
-- makes a new function signature. The old ones are dropped before the new ones
-- are created: leaving them in place would leave two overloads for the same
-- PostgREST call, and PostgREST cannot choose between them.
--
-- Nothing in 0001-0007 is edited.
-- =============================================================================

alter table public.products add column if not exists product_link text;
alter table public.products add column if not exists campaign text;
alter table public.products add column if not exists asin_code text;

comment on column public.products.product_link is
  'Amazon product URL. Null when the admin has not recorded one.';
comment on column public.products.campaign is
  'Free-text campaign label the product is filed under.';
comment on column public.products.asin_code is
  'Amazon ASIN, stored upper-cased. Null when unknown.';

-- Added conditionally so re-running this file stays a no-op. The same rules are
-- enforced in the admin functions below; these constraints are the backstop if a
-- row is ever written another way.
do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'products_product_link_shape') then
    alter table public.products
      add constraint products_product_link_shape
      check (product_link is null or (length(product_link) between 8 and 1024 and product_link ~* '^https?://'));
  end if;

  if not exists (select 1 from pg_constraint where conname = 'products_campaign_length') then
    alter table public.products
      add constraint products_campaign_length
      check (campaign is null or length(btrim(campaign)) between 1 and 120);
  end if;

  if not exists (select 1 from pg_constraint where conname = 'products_asin_code_shape') then
    alter table public.products
      add constraint products_asin_code_shape
      check (asin_code is null or asin_code ~ '^[A-Z0-9]{10}$');
  end if;
end;
$$;

-- -----------------------------------------------------------------------------
-- admin_create_product, extended with the new detail fields.
-- -----------------------------------------------------------------------------
drop function if exists public.admin_create_product(text, text, text, text, int, numeric);

create or replace function public.admin_create_product(
  p_name text,
  p_brand text default null,
  p_description text default null,
  p_image_url text default null,
  p_total_slots int default 1,
  p_cashback_amount numeric default null,
  p_product_link text default null,
  p_campaign text default null,
  p_asin_code text default null
)
returns public.products
language plpgsql
security definer
set search_path = public
as $$
declare
  v_admin uuid := public.assert_admin();
  v_product public.products;
  v_link text := nullif(btrim(coalesce(p_product_link, '')), '');
  v_campaign text := nullif(btrim(coalesce(p_campaign, '')), '');
  v_asin text := upper(nullif(btrim(coalesce(p_asin_code, '')), ''));
begin
  if length(btrim(coalesce(p_name, ''))) = 0 then
    raise exception 'product name is required' using errcode = 'P0001';
  end if;
  if p_total_slots is null or p_total_slots < 1 or p_total_slots > 100000 then
    raise exception 'total_slots must be between 1 and 100000' using errcode = 'P0001';
  end if;
  if p_cashback_amount is not null and p_cashback_amount < 0 then
    raise exception 'cashback_amount cannot be negative' using errcode = 'P0001';
  end if;
  if v_link is not null and (length(v_link) > 1024 or v_link !~* '^https?://') then
    raise exception 'product_link must be a full http(s) URL' using errcode = 'P0001';
  end if;
  if v_campaign is not null and length(v_campaign) > 120 then
    raise exception 'campaign must be 120 characters or fewer' using errcode = 'P0001';
  end if;
  if v_asin is not null and v_asin !~ '^[A-Z0-9]{10}$' then
    raise exception 'asin_code must be exactly 10 letters or digits' using errcode = 'P0001';
  end if;

  insert into public.products (
    name, brand, description, image_url, total_slots, cashback_amount, status, created_by,
    product_link, campaign, asin_code
  )
  values (
    btrim(p_name),
    nullif(btrim(coalesce(p_brand, '')), ''),
    nullif(btrim(coalesce(p_description, '')), ''),
    nullif(btrim(coalesce(p_image_url, '')), ''),
    p_total_slots,
    p_cashback_amount,
    'open',
    v_admin,
    v_link,
    v_campaign,
    v_asin
  )
  returning * into v_product;

  insert into public.audit_log (admin_id, action, target_table, target_id, details)
  values (
    v_admin,
    'create_product',
    'products',
    v_product.id,
    jsonb_build_object(
      'name', v_product.name,
      'brand', v_product.brand,
      'total_slots', v_product.total_slots,
      'cashback_amount', v_product.cashback_amount,
      'product_link', v_product.product_link,
      'campaign', v_product.campaign,
      'asin_code', v_product.asin_code
    )
  );

  return v_product;
end;
$$;

-- -----------------------------------------------------------------------------
-- admin_update_product, extended the same way.
--
-- The new fields follow the existing convention: null leaves the stored value
-- alone, an empty string clears it.
-- -----------------------------------------------------------------------------
drop function if exists public.admin_update_product(uuid, text, text, text, text, int, numeric, text);

create or replace function public.admin_update_product(
  p_product_id uuid,
  p_name text default null,
  p_brand text default null,
  p_description text default null,
  p_image_url text default null,
  p_total_slots int default null,
  p_cashback_amount numeric default null,
  p_status text default null,
  p_product_link text default null,
  p_campaign text default null,
  p_asin_code text default null
)
returns public.products
language plpgsql
security definer
set search_path = public
as $$
declare
  v_admin uuid := public.assert_admin();
  v_product public.products;
  v_before public.products;
  v_link text;
  v_campaign text;
  v_asin text;
begin
  select * into v_before from public.products where id = p_product_id for update;
  if not found then
    raise exception 'product not found' using errcode = 'P0002';
  end if;

  if p_status is not null and p_status not in ('open', 'closed') then
    raise exception 'invalid product status' using errcode = 'P0001';
  end if;
  if p_name is not null and length(btrim(p_name)) = 0 then
    raise exception 'product name cannot be empty' using errcode = 'P0001';
  end if;
  if p_total_slots is not null and (p_total_slots < 1 or p_total_slots > 100000) then
    raise exception 'total_slots must be between 1 and 100000' using errcode = 'P0001';
  end if;
  if p_total_slots is not null and p_total_slots < v_before.slots_filled then
    raise exception 'total_slots cannot be lower than the % slots already filled', v_before.slots_filled
      using errcode = 'P0001';
  end if;
  if p_cashback_amount is not null and p_cashback_amount < 0 then
    raise exception 'cashback_amount cannot be negative' using errcode = 'P0001';
  end if;

  -- Only validated when the caller is actually changing the field, so an
  -- unrelated edit to an old row can never be blocked by it.
  if p_product_link is not null then
    v_link := nullif(btrim(p_product_link), '');
    if v_link is not null and (length(v_link) > 1024 or v_link !~* '^https?://') then
      raise exception 'product_link must be a full http(s) URL' using errcode = 'P0001';
    end if;
  end if;

  if p_campaign is not null then
    v_campaign := nullif(btrim(p_campaign), '');
    if v_campaign is not null and length(v_campaign) > 120 then
      raise exception 'campaign must be 120 characters or fewer' using errcode = 'P0001';
    end if;
  end if;

  if p_asin_code is not null then
    v_asin := upper(nullif(btrim(p_asin_code), ''));
    if v_asin is not null and v_asin !~ '^[A-Z0-9]{10}$' then
      raise exception 'asin_code must be exactly 10 letters or digits' using errcode = 'P0001';
    end if;
  end if;

  update public.products
     set name = coalesce(nullif(btrim(coalesce(p_name, '')), ''), name),
         brand = case when p_brand is null then brand else nullif(btrim(p_brand), '') end,
         description = case when p_description is null then description else nullif(btrim(p_description), '') end,
         image_url = case when p_image_url is null then image_url else nullif(btrim(p_image_url), '') end,
         total_slots = coalesce(p_total_slots, total_slots),
         cashback_amount = coalesce(p_cashback_amount, cashback_amount),
         status = coalesce(p_status, status),
         product_link = case when p_product_link is null then product_link else v_link end,
         campaign = case when p_campaign is null then campaign else v_campaign end,
         asin_code = case when p_asin_code is null then asin_code else v_asin end
   where id = p_product_id
   returning * into v_product;

  insert into public.audit_log (admin_id, action, target_table, target_id, details)
  values (
    v_admin,
    case
      when p_status = 'closed' and v_before.status <> 'closed' then 'close_product'
      when p_status = 'open' and v_before.status <> 'open' then 'reopen_product'
      else 'update_product'
    end,
    'products',
    p_product_id,
    jsonb_build_object(
      'before', jsonb_build_object(
        'name', v_before.name, 'brand', v_before.brand, 'total_slots', v_before.total_slots,
        'cashback_amount', v_before.cashback_amount, 'status', v_before.status,
        'product_link', v_before.product_link, 'campaign', v_before.campaign,
        'asin_code', v_before.asin_code
      ),
      'after', jsonb_build_object(
        'name', v_product.name, 'brand', v_product.brand, 'total_slots', v_product.total_slots,
        'cashback_amount', v_product.cashback_amount, 'status', v_product.status,
        'product_link', v_product.product_link, 'campaign', v_product.campaign,
        'asin_code', v_product.asin_code
      )
    )
  );

  return v_product;
end;
$$;

-- The drops above took the old grants with them, so they are re-issued here. The
-- functions self-check with assert_admin() as well.
revoke all on function public.admin_create_product(text, text, text, text, int, numeric, text, text, text) from public;
revoke all on function public.admin_update_product(uuid, text, text, text, text, int, numeric, text, text, text, text) from public;
revoke execute on function public.admin_create_product(text, text, text, text, int, numeric, text, text, text) from anon;
revoke execute on function public.admin_update_product(uuid, text, text, text, text, int, numeric, text, text, text, text) from anon;
grant execute on function public.admin_create_product(text, text, text, text, int, numeric, text, text, text) to authenticated;
grant execute on function public.admin_update_product(uuid, text, text, text, text, int, numeric, text, text, text, text) to authenticated;


-- ----------------------------------------------------------------------------
-- >>> 0009_remove_order_approval.sql
-- ----------------------------------------------------------------------------
-- =============================================================================
-- 0009  The order-approval stage is gone.
--
-- Submitting a confirmed order proof now moves the order straight to
-- review_pending. Nobody has to verify the purchase screenshot first; it is
-- still collected and stored on the order for the record.
--
-- What this changes
--   * submit_order_proof()  - writes review_pending instead of order_submitted
--   * enforce_order_update_guard() - allowed transitions follow
--
-- What this deliberately does NOT change
--   * The orders.status CHECK still lists order_confirmed. Dropping a value from
--     a live check constraint is a breaking migration, so the value stays legal
--     for rows that already carry it - it is simply never written again.
--   * admin_transition_order() is untouched: the review queue still uses it to
--     move review_submitted -> approved/rejected.
--   * order_confirmed_at and its trigger stay, for the same reason.
--
-- Nothing in 0001-0008 is edited; the two functions below are replaced.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- Existing rows sitting in the retired stage.
--
-- order_submitted can no longer be reached or advanced from the app, so without
-- this a reviewer whose screenshot was already in would be stuck with no way
-- forward. They did what was asked of them, so they move to the review step.
-- Idempotent, and a no-op once no rows carry the old status.
-- -----------------------------------------------------------------------------
update public.orders
   set status = 'review_pending'
 where status = 'order_submitted';

-- -----------------------------------------------------------------------------
-- enforce_order_update_guard, with the approval step removed.
--
-- The only intended differences from the 0006 version:
--   * claimed -> review_pending is now the legal transition (was
--     claimed -> order_submitted);
--   * claimed -> order_submitted is no longer offered, so nothing can put a row
--     back into the retired stage;
--   * order_submitted -> review_pending is kept as a one-way escape hatch, so a
--     row that somehow lands in the retired stage is never permanently stuck.
-- Everything else, including which fields are admin-only and when proof becomes
-- immutable, is unchanged.
-- -----------------------------------------------------------------------------
create or replace function public.enforce_order_update_guard()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  -- No JWT in the request context means service_role / server-side code.
  if auth.uid() is null or public.is_admin(auth.uid()) then
    return new;
  end if;

  if new.user_id is distinct from old.user_id then
    raise exception 'orders.user_id is immutable' using errcode = '42501';
  end if;
  if new.product_id is distinct from old.product_id then
    raise exception 'orders.product_id is immutable' using errcode = '42501';
  end if;

  -- Admin-only for the whole lifetime of the row.
  if new.order_confirmed_at is distinct from old.order_confirmed_at
     or new.review_submitted_at is distinct from old.review_submitted_at
     or new.approved_at is distinct from old.approved_at
     or new.paid_at is distinct from old.paid_at
     or new.payment_reference is distinct from old.payment_reference
     or new.rejection_reason is distinct from old.rejection_reason
  then
    raise exception 'only admins may modify administrative order fields' using errcode = '42501';
  end if;

  -- Owner-editable only while the claim is still unsubmitted.
  if old.status <> 'claimed' and (
       new.extracted_name is distinct from old.extracted_name
    or new.extracted_order_id is distinct from old.extracted_order_id
    or new.extracted_phone is distinct from old.extracted_phone
    or new.extracted_product_name is distinct from old.extracted_product_name
    or new.order_screenshot_url is distinct from old.order_screenshot_url
  ) then
    raise exception 'order proof is locked once the order has been submitted'
      using errcode = '42501';
  end if;

  -- Review proof is editable only while the review is still owed. order_confirmed
  -- stays in this list because existing rows still carry it.
  if old.status not in ('order_confirmed', 'review_pending') and (
       new.review_screenshot_url is distinct from old.review_screenshot_url
    or new.review_link is distinct from old.review_link
  ) then
    raise exception 'review proof is locked once the review has been submitted'
      using errcode = '42501';
  end if;

  if new.status is distinct from old.status then
    if not (
      (old.status = 'claimed' and new.status = 'review_pending')
      or (old.status = 'order_submitted' and new.status = 'review_pending')
      or (old.status = 'order_confirmed' and new.status = 'review_submitted')
      or (old.status = 'review_pending' and new.status = 'review_submitted')
    ) then
      raise exception 'illegal order status transition: % -> %', old.status, new.status
        using errcode = '42501';
    end if;

    -- Submitting the order proof is only meaningful once the user has confirmed
    -- what the extraction read.
    if old.status = 'claimed' and new.status = 'review_pending' and new.user_confirmed is not true then
      raise exception 'confirm the order details before submitting' using errcode = '42501';
    end if;

    -- A review submission needs at least one form of proof.
    if old.status in ('order_confirmed', 'review_pending')
       and new.status = 'review_submitted'
       and coalesce(new.review_screenshot_url, new.review_link) is null
    then
      raise exception 'attach a review screenshot or paste the review link'
        using errcode = '42501';
    end if;
  end if;

  return new;
end;
$$;

-- -----------------------------------------------------------------------------
-- submit_order_proof, now landing in review_pending.
--
-- The screenshot is still recorded on the order - it is kept as the record of
-- what was bought - it just no longer gates anything. Everything else about this
-- function (ownership, verified phone, path prefix, field validation) is
-- unchanged from 0006.
-- -----------------------------------------------------------------------------
create or replace function public.submit_order_proof(
  p_order_id uuid,
  p_screenshot_path text,
  p_name text default null,
  p_order_ref text default null,
  p_phone text default null,
  p_product_name text default null
)
returns public.orders
language plpgsql
security definer
set search_path = public
as $$
declare
  v_user uuid := public.assert_verified_user();
  v_order public.orders;
  v_path text := btrim(coalesce(p_screenshot_path, ''));
  v_name text := nullif(btrim(coalesce(p_name, '')), '');
  v_ref text := nullif(btrim(coalesce(p_order_ref, '')), '');
  v_phone text := nullif(btrim(coalesce(p_phone, '')), '');
  v_product text := nullif(btrim(coalesce(p_product_name, '')), '');
begin
  select * into v_order
    from public.orders
   where id = p_order_id and user_id = v_user
   for update;

  if not found then
    raise exception 'order not found' using errcode = 'P0002', hint = 'order_not_found';
  end if;

  if v_order.status <> 'claimed' then
    raise exception 'this order has already been submitted'
      using errcode = 'P0001', hint = 'order_locked';
  end if;

  if length(v_path) = 0 or v_path not like v_user::text || '/%' then
    raise exception 'invalid screenshot path' using errcode = '42501', hint = 'invalid_path';
  end if;

  if v_ref is null or length(v_ref) < 3 then
    raise exception 'the order id from the screenshot is required'
      using errcode = 'P0001', hint = 'order_ref_required';
  end if;

  if length(v_path) > 1024
     or (v_name is not null and length(v_name) > 200)
     or length(v_ref) > 200
     or (v_phone is not null and (length(v_phone) > 40 or v_phone !~ '^[0-9+][0-9+ -]{4,39}$'))
     or (v_product is not null and length(v_product) > 300)
  then
    raise exception 'one of the submitted fields is not valid'
      using errcode = 'P0001', hint = 'invalid_field';
  end if;

  update public.orders
     set order_screenshot_url = v_path,
         extracted_name = v_name,
         extracted_order_id = v_ref,
         extracted_phone = v_phone,
         extracted_product_name = v_product,
         user_confirmed = true,
         status = 'review_pending'
   where id = p_order_id
   returning * into v_order;

  return v_order;
end;
$$;

revoke all on function public.submit_order_proof(uuid, text, text, text, text, text) from public;
revoke execute on function public.submit_order_proof(uuid, text, text, text, text, text) from anon;
grant execute on function public.submit_order_proof(uuid, text, text, text, text, text) to authenticated;


-- ----------------------------------------------------------------------------
-- >>> 0010_daily_slot_release.sql
-- ----------------------------------------------------------------------------
-- =============================================================================
-- 0010  Daily staggered slot release.
--
-- A product can open its slots a few at a time instead of all at once.
--
--   daily_release_limit  how many slots open per day. NULL keeps the original
--                        behaviour: every slot is claimable immediately.
--   released_slots       how many slots are claimable right now. Claims compare
--                        slots_filled against THIS, never against total_slots.
--   last_release_date    the IST calendar day the daily job last topped this
--                        product up.
--
-- released_slots never decreases (except when an admin lowers total_slots below
-- it, where it is clamped), so yesterday's unclaimed slots stay in the pool and
-- add to today's release. That is the whole rollover story - there is no
-- separate carry-forward counter to keep in sync.
--
-- The calendar is IST because the business runs in India and the job fires at
-- midnight there. 00:00 IST is 18:30 UTC the previous day, which is the cron
-- expression below. pg_cron schedules in the database time zone (UTC on
-- Supabase); if a project runs its database in another zone, change the
-- expression to match.
--
-- Nothing in 0001-0009 is edited. The two admin functions are dropped and
-- recreated because a new parameter changes their signature, exactly as 0008
-- did.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- Columns, backfilled so every existing product behaves exactly as it did.
-- -----------------------------------------------------------------------------
alter table public.products
  add column if not exists daily_release_limit int,
  add column if not exists released_slots int,
  add column if not exists last_release_date date;

update public.products
   set released_slots = total_slots
 where released_slots is null;

update public.products
   set last_release_date = (created_at at time zone 'Asia/Kolkata')::date
 where last_release_date is null;

alter table public.products
  alter column released_slots set not null;

alter table public.products
  alter column last_release_date set default (now() at time zone 'Asia/Kolkata')::date;

alter table public.products
  alter column last_release_date set not null;

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'products_daily_release_limit_positive') then
    alter table public.products
      add constraint products_daily_release_limit_positive
      check (daily_release_limit is null or daily_release_limit > 0);
  end if;

  -- The new hard invariant: nobody can hold more slots than have been released,
  -- and nothing can be released beyond total_slots. This is the backstop for the
  -- claim rule below, the way products_slots_bounds backstops the old one.
  if not exists (select 1 from pg_constraint where conname = 'products_released_bounds') then
    alter table public.products
      add constraint products_released_bounds
      check (
        released_slots >= 0
        and released_slots <= total_slots
        and slots_filled <= released_slots
      );
  end if;
end;
$$;

-- -----------------------------------------------------------------------------
-- Insert defaults.
--
-- released_slots has to be derived from daily_release_limit (or total_slots when
-- there is no limit), and a column DEFAULT cannot reference another column, so
-- it is set by a BEFORE INSERT trigger. last_release_date starts on the day the
-- product was created.
-- -----------------------------------------------------------------------------
create or replace function public.set_product_release_defaults()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if new.daily_release_limit is not null and new.daily_release_limit < 1 then
    raise exception 'daily_release_limit must be a positive number of slots'
      using errcode = 'P0001';
  end if;

  if new.released_slots is null then
    -- No limit means "everything is open now", which is the historical behaviour.
    new.released_slots := least(
      coalesce(new.daily_release_limit, new.total_slots),
      new.total_slots
    );
  end if;

  if new.last_release_date is null then
    new.last_release_date := (now() at time zone 'Asia/Kolkata')::date;
  end if;

  return new;
end;
$$;

drop trigger if exists products_release_defaults_before_insert on public.products;
create trigger products_release_defaults_before_insert
  before insert on public.products
  for each row execute function public.set_product_release_defaults();

-- -----------------------------------------------------------------------------
-- claim_product_slot, now bounded by released_slots.
--
-- Still a single UPDATE ... WHERE, so Postgres serialises concurrent claimants
-- and exactly one of them can take the last released slot. The only change from
-- the 0003 version is which column the availability test reads: a product with
-- 50 slots and a daily release of 5 takes 5 claims on day one, not 50.
-- -----------------------------------------------------------------------------
create or replace function public.claim_product_slot(p_product_id uuid)
returns boolean
language plpgsql
security definer
set search_path = public
as $$
declare
  v_updated int;
begin
  if auth.uid() is null then
    raise exception 'authentication required' using errcode = '42501';
  end if;

  update public.products
     set slots_filled = slots_filled + 1
   where id = p_product_id
     and status = 'open'
     and slots_filled < released_slots;

  get diagnostics v_updated = row_count;
  return v_updated = 1;
end;
$$;

comment on function public.claim_product_slot(uuid) is
  'Atomically consumes one released product slot. Returns false when the released batch is gone, closed or unknown.';

revoke all on function public.claim_product_slot(uuid) from public;
revoke execute on function public.claim_product_slot(uuid) from anon;
grant execute on function public.claim_product_slot(uuid) to authenticated;

-- -----------------------------------------------------------------------------
-- release_daily_slots: the job body.
--
-- Deliberately date-driven rather than "add one batch": it computes the number
-- of days since last_release_date and adds daily_release_limit per elapsed day,
-- capped at total_slots. A missed run (cron paused, function failing, weekend
-- maintenance) therefore catches up on the next run instead of losing a batch.
-- Only open products with a limit are touched, and last_release_date moves to
-- today in the same statement, so a double run on the same day is a no-op.
--
-- Returns how many products it topped up, which makes it easy to run by hand
-- and see what it did.
-- -----------------------------------------------------------------------------
create or replace function public.release_daily_slots()
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  v_today date := (now() at time zone 'Asia/Kolkata')::date;
  v_released int;
begin
  with advanced as (
    update public.products
       set released_slots = least(
             total_slots,
             released_slots + daily_release_limit * (v_today - last_release_date)
           ),
           last_release_date = v_today
     where status = 'open'
       and daily_release_limit is not null
       and released_slots < total_slots
       and last_release_date < v_today
    returning 1
  )
  select count(*)::int into v_released from advanced;

  return v_released;
end;
$$;

comment on function public.release_daily_slots() is
  'Advances released_slots by daily_release_limit per elapsed day (capped at total_slots) for every open product that has a limit. Idempotent within a day.';

-- Only the scheduler and the server may drive releases; a signed-in user must
-- not be able to open a batch early.
revoke all on function public.release_daily_slots() from public;
revoke execute on function public.release_daily_slots() from anon, authenticated;
grant execute on function public.release_daily_slots() to service_role;

-- -----------------------------------------------------------------------------
-- Schedule it: every day at 00:00 IST.
--
-- Wrapped in an exception handler on purpose. pg_cron is an extension the
-- project owner has to enable, and it is not available in the in-process test
-- database at all, so a hard `create extension` would make this migration fail
-- everywhere it is not pre-installed. When it cannot be scheduled the function
-- above still exists and works - the notice says exactly what to do.
-- -----------------------------------------------------------------------------
do $$
begin
  begin
    create extension if not exists pg_cron;
  exception when others then
    raise notice 'pg_cron is not available here (%); release_daily_slots() exists but is not scheduled. Enable pg_cron (Database > Extensions) and re-run this file.', sqlerrm;
  end;

  if exists (select 1 from pg_extension where extname = 'pg_cron') then
    -- Unscheduled first so re-running this file never stacks duplicate jobs.
    begin
      perform cron.unschedule(jobid) from cron.job where jobname = 'daily_slot_release';
    exception when others then
      null;
    end;

    perform cron.schedule(
      'daily_slot_release',
      '30 18 * * *',
      $cron$select public.release_daily_slots();$cron$
    );

    raise notice 'pg_cron job daily_slot_release scheduled for 00:00 IST (18:30 UTC).';
  end if;
end;
$$;

-- -----------------------------------------------------------------------------
-- admin_create_product, extended with the daily release limit.
--
-- A limit of 0 or null means "no staggering": the trigger then releases every
-- slot immediately, which is exactly what the console did before.
-- -----------------------------------------------------------------------------
drop function if exists public.admin_create_product(text, text, text, text, int, numeric, text, text, text);

create or replace function public.admin_create_product(
  p_name text,
  p_brand text default null,
  p_description text default null,
  p_image_url text default null,
  p_total_slots int default 1,
  p_cashback_amount numeric default null,
  p_product_link text default null,
  p_campaign text default null,
  p_asin_code text default null,
  p_daily_release_limit int default null
)
returns public.products
language plpgsql
security definer
set search_path = public
as $$
declare
  v_admin uuid := public.assert_admin();
  v_product public.products;
  v_link text := nullif(btrim(coalesce(p_product_link, '')), '');
  v_campaign text := nullif(btrim(coalesce(p_campaign, '')), '');
  v_asin text := upper(nullif(btrim(coalesce(p_asin_code, '')), ''));
  v_limit int := nullif(p_daily_release_limit, 0);
begin
  if length(btrim(coalesce(p_name, ''))) = 0 then
    raise exception 'product name is required' using errcode = 'P0001';
  end if;
  if p_total_slots is null or p_total_slots < 1 or p_total_slots > 100000 then
    raise exception 'total_slots must be between 1 and 100000' using errcode = 'P0001';
  end if;
  if p_cashback_amount is not null and p_cashback_amount < 0 then
    raise exception 'cashback_amount cannot be negative' using errcode = 'P0001';
  end if;
  if v_link is not null and (length(v_link) > 1024 or v_link !~* '^https?://') then
    raise exception 'product_link must be a full http(s) URL' using errcode = 'P0001';
  end if;
  if v_campaign is not null and length(v_campaign) > 120 then
    raise exception 'campaign must be 120 characters or fewer' using errcode = 'P0001';
  end if;
  if v_asin is not null and v_asin !~ '^[A-Z0-9]{10}$' then
    raise exception 'asin_code must be exactly 10 letters or digits' using errcode = 'P0001';
  end if;
  if v_limit is not null and (v_limit < 1 or v_limit > 100000) then
    raise exception 'daily_release_limit must be between 1 and 100000 slots' using errcode = 'P0001';
  end if;

  insert into public.products (
    name, brand, description, image_url, total_slots, cashback_amount, status, created_by,
    product_link, campaign, asin_code, daily_release_limit
  )
  values (
    btrim(p_name),
    nullif(btrim(coalesce(p_brand, '')), ''),
    nullif(btrim(coalesce(p_description, '')), ''),
    nullif(btrim(coalesce(p_image_url, '')), ''),
    p_total_slots,
    p_cashback_amount,
    'open',
    v_admin,
    v_link,
    v_campaign,
    v_asin,
    v_limit
  )
  returning * into v_product;

  insert into public.audit_log (admin_id, action, target_table, target_id, details)
  values (
    v_admin,
    'create_product',
    'products',
    v_product.id,
    jsonb_build_object(
      'name', v_product.name,
      'brand', v_product.brand,
      'total_slots', v_product.total_slots,
      'released_slots', v_product.released_slots,
      'daily_release_limit', v_product.daily_release_limit,
      'cashback_amount', v_product.cashback_amount,
      'product_link', v_product.product_link,
      'campaign', v_product.campaign,
      'asin_code', v_product.asin_code
    )
  );

  return v_product;
end;
$$;

-- -----------------------------------------------------------------------------
-- admin_update_product, extended the same way.
--
-- null leaves the limit alone (so an unrelated edit, or the close/reopen action,
-- cannot clear it by accident), 0 removes it, any other number sets it.
-- Lowering total_slots clamps released_slots, because released_slots is never
-- allowed to exceed it. Changing the limit never rewinds released_slots: slots
-- that are already open cannot be un-opened.
-- -----------------------------------------------------------------------------
drop function if exists public.admin_update_product(uuid, text, text, text, text, int, numeric, text, text, text, text);

create or replace function public.admin_update_product(
  p_product_id uuid,
  p_name text default null,
  p_brand text default null,
  p_description text default null,
  p_image_url text default null,
  p_total_slots int default null,
  p_cashback_amount numeric default null,
  p_status text default null,
  p_product_link text default null,
  p_campaign text default null,
  p_asin_code text default null,
  p_daily_release_limit int default null
)
returns public.products
language plpgsql
security definer
set search_path = public
as $$
declare
  v_admin uuid := public.assert_admin();
  v_before public.products;
  v_product public.products;
  v_link text;
  v_campaign text;
  v_asin text;
begin
  select * into v_before from public.products where id = p_product_id for update;
  if not found then
    raise exception 'product not found' using errcode = 'P0002';
  end if;

  if p_status is not null and p_status not in ('open', 'closed') then
    raise exception 'invalid product status' using errcode = 'P0001';
  end if;
  if p_name is not null and length(btrim(p_name)) = 0 then
    raise exception 'product name cannot be empty' using errcode = 'P0001';
  end if;
  if p_total_slots is not null and (p_total_slots < 1 or p_total_slots > 100000) then
    raise exception 'total_slots must be between 1 and 100000' using errcode = 'P0001';
  end if;
  if p_total_slots is not null and p_total_slots < v_before.slots_filled then
    raise exception 'total_slots cannot be lower than the % slots already filled', v_before.slots_filled
      using errcode = 'P0001';
  end if;
  if p_cashback_amount is not null and p_cashback_amount < 0 then
    raise exception 'cashback_amount cannot be negative' using errcode = 'P0001';
  end if;
  if p_daily_release_limit is not null
     and (p_daily_release_limit < 0 or p_daily_release_limit > 100000)
  then
    raise exception 'daily_release_limit must be between 1 and 100000 slots, or 0 to remove it'
      using errcode = 'P0001';
  end if;

  -- Only validated when the caller is actually changing the field, so an
  -- unrelated edit to an old row can never be blocked by it.
  if p_product_link is not null then
    v_link := nullif(btrim(p_product_link), '');
    if v_link is not null and (length(v_link) > 1024 or v_link !~* '^https?://') then
      raise exception 'product_link must be a full http(s) URL' using errcode = 'P0001';
    end if;
  end if;

  if p_campaign is not null then
    v_campaign := nullif(btrim(p_campaign), '');
    if v_campaign is not null and length(v_campaign) > 120 then
      raise exception 'campaign must be 120 characters or fewer' using errcode = 'P0001';
    end if;
  end if;

  if p_asin_code is not null then
    v_asin := upper(nullif(btrim(p_asin_code), ''));
    if v_asin is not null and v_asin !~ '^[A-Z0-9]{10}$' then
      raise exception 'asin_code must be exactly 10 letters or digits' using errcode = 'P0001';
    end if;
  end if;

  update public.products
     set name = coalesce(nullif(btrim(coalesce(p_name, '')), ''), name),
         brand = case when p_brand is null then brand else nullif(btrim(p_brand), '') end,
         description = case when p_description is null then description else nullif(btrim(p_description), '') end,
         image_url = case when p_image_url is null then image_url else nullif(btrim(p_image_url), '') end,
         total_slots = coalesce(p_total_slots, total_slots),
         released_slots = least(released_slots, coalesce(p_total_slots, total_slots)),
         cashback_amount = coalesce(p_cashback_amount, cashback_amount),
         status = coalesce(p_status, status),
         product_link = case when p_product_link is null then product_link else v_link end,
         campaign = case when p_campaign is null then campaign else v_campaign end,
         asin_code = case when p_asin_code is null then asin_code else v_asin end,
         daily_release_limit = case
           when p_daily_release_limit is null then daily_release_limit
           when p_daily_release_limit = 0 then null
           else p_daily_release_limit
         end
   where id = p_product_id
   returning * into v_product;

  insert into public.audit_log (admin_id, action, target_table, target_id, details)
  values (
    v_admin,
    case
      when p_status = 'closed' and v_before.status <> 'closed' then 'close_product'
      when p_status = 'open' and v_before.status <> 'open' then 'reopen_product'
      else 'update_product'
    end,
    'products',
    p_product_id,
    jsonb_build_object(
      'before', jsonb_build_object(
        'name', v_before.name, 'brand', v_before.brand, 'total_slots', v_before.total_slots,
        'released_slots', v_before.released_slots,
        'daily_release_limit', v_before.daily_release_limit,
        'cashback_amount', v_before.cashback_amount, 'status', v_before.status,
        'product_link', v_before.product_link, 'campaign', v_before.campaign,
        'asin_code', v_before.asin_code
      ),
      'after', jsonb_build_object(
        'name', v_product.name, 'brand', v_product.brand, 'total_slots', v_product.total_slots,
        'released_slots', v_product.released_slots,
        'daily_release_limit', v_product.daily_release_limit,
        'cashback_amount', v_product.cashback_amount, 'status', v_product.status,
        'product_link', v_product.product_link, 'campaign', v_product.campaign,
        'asin_code', v_product.asin_code
      )
    )
  );

  return v_product;
end;
$$;

-- The drops above took the old grants with them, so they are re-issued here. The
-- functions self-check with assert_admin() as well.
revoke all on function public.admin_create_product(text, text, text, text, int, numeric, text, text, text, int) from public;
revoke all on function public.admin_update_product(uuid, text, text, text, text, int, numeric, text, text, text, text, int) from public;
revoke execute on function public.admin_create_product(text, text, text, text, int, numeric, text, text, text, int) from anon;
revoke execute on function public.admin_update_product(uuid, text, text, text, text, int, numeric, text, text, text, text, int) from anon;
grant execute on function public.admin_create_product(text, text, text, text, int, numeric, text, text, text, int) to authenticated;
grant execute on function public.admin_update_product(uuid, text, text, text, text, int, numeric, text, text, text, text, int) to authenticated;


-- ----------------------------------------------------------------------------
-- >>> 0011_brands.sql
-- ----------------------------------------------------------------------------
-- =============================================================================
-- 0011  Brands.
--
-- A brand is an advertiser entity that owns campaigns and products. It stores
-- point-of-contact info so the ops team can reach the brand owner directly.
--
-- Rules:
--   * Admin-only table: no end-user RLS policy exists, so any authenticated
--     non-admin request is blocked by default-deny.
--   * All mutations go through SECURITY DEFINER RPCs that call assert_admin()
--     and write the audit_log in the same transaction.
--   * Deletion is blocked when the brand is referenced by campaigns or products
--     (soft referential protection — no FK enforces this at the schema level so
--     that campaigns / products can land in a later migration without needing to
--     backfill brand_id first).
--   * brand_seq is a bigserial that drives the human-readable BR-NNN id shown
--     in the UI.  The formatted id is computed in the client layer as
--     'BR-' || lpad(brand_seq::text, 3, '0') so no extra view is needed.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- Table
-- -----------------------------------------------------------------------------
create table if not exists public.brands (
  id           uuid         primary key default gen_random_uuid(),
  brand_seq    bigint       generated always as identity,
  name         text         not null,
  poc_name     text,
  poc_number   text,
  poc_email    text,
  website      text,
  created_by   uuid         references public.profiles(id),
  created_at   timestamptz  not null default now(),
  updated_at   timestamptz  not null default now()
);

comment on table  public.brands                is 'Advertiser brands. Admin-only; no end-user access.';
comment on column public.brands.brand_seq      is 'Monotonic sequence used to build the human-readable BR-NNN display id.';
comment on column public.brands.poc_name       is 'Point-of-contact name at the brand.';
comment on column public.brands.poc_number     is 'Point-of-contact phone/WhatsApp at the brand.';
comment on column public.brands.poc_email      is 'Point-of-contact e-mail at the brand.';

-- -----------------------------------------------------------------------------
-- updated_at trigger (reuse the shared helper from 0003 if it exists, otherwise
-- create a local one using the same body).
-- -----------------------------------------------------------------------------
create or replace function public.set_brands_updated_at()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  new.updated_at := now();
  return new;
end;
$$;

drop trigger if exists brands_set_updated_at on public.brands;
create trigger brands_set_updated_at
  before update on public.brands
  for each row execute function public.set_brands_updated_at();

-- -----------------------------------------------------------------------------
-- RLS — admin-only (no end-user policies; default-deny blocks everyone else).
-- -----------------------------------------------------------------------------
alter table public.brands enable row level security;

drop policy if exists brands_select_admin on public.brands;
drop policy if exists brands_insert_admin on public.brands;
drop policy if exists brands_update_admin on public.brands;
drop policy if exists brands_delete_admin on public.brands;

create policy brands_select_admin on public.brands
  for select to authenticated
  using (public.is_admin());

create policy brands_insert_admin on public.brands
  for insert to authenticated
  with check (public.is_admin());

create policy brands_update_admin on public.brands
  for update to authenticated
  using (public.is_admin())
  with check (public.is_admin());

create policy brands_delete_admin on public.brands
  for delete to authenticated
  using (public.is_admin());

-- -----------------------------------------------------------------------------
-- admin_create_brand
-- -----------------------------------------------------------------------------
create or replace function public.admin_create_brand(
  p_name       text,
  p_poc_name   text default null,
  p_poc_number text default null,
  p_poc_email  text default null,
  p_website    text default null
)
returns public.brands
language plpgsql
security definer
set search_path = public
as $$
declare
  v_admin  uuid := public.assert_admin();
  v_brand  public.brands;
  v_name   text := btrim(coalesce(p_name, ''));
  v_website text := nullif(btrim(coalesce(p_website, '')), '');
begin
  if length(v_name) = 0 then
    raise exception 'brand name is required' using errcode = 'P0001';
  end if;
  if length(v_name) > 200 then
    raise exception 'brand name must be 200 characters or fewer' using errcode = 'P0001';
  end if;
  if v_website is not null and v_website !~* '^https?://' then
    raise exception 'website must be a full http(s) URL' using errcode = 'P0001';
  end if;

  insert into public.brands (name, poc_name, poc_number, poc_email, website, created_by)
  values (
    v_name,
    nullif(btrim(coalesce(p_poc_name,   '')), ''),
    nullif(btrim(coalesce(p_poc_number, '')), ''),
    nullif(btrim(coalesce(p_poc_email,  '')), ''),
    v_website,
    v_admin
  )
  returning * into v_brand;

  insert into public.audit_log (admin_id, action, target_table, target_id, details)
  values (
    v_admin,
    'create_brand',
    'brands',
    v_brand.id,
    jsonb_build_object(
      'name',       v_brand.name,
      'poc_name',   v_brand.poc_name,
      'poc_email',  v_brand.poc_email,
      'website',    v_brand.website
    )
  );

  return v_brand;
end;
$$;

-- -----------------------------------------------------------------------------
-- admin_update_brand
-- -----------------------------------------------------------------------------
create or replace function public.admin_update_brand(
  p_brand_id   uuid,
  p_name       text default null,
  p_poc_name   text default null,
  p_poc_number text default null,
  p_poc_email  text default null,
  p_website    text default null
)
returns public.brands
language plpgsql
security definer
set search_path = public
as $$
declare
  v_admin   uuid := public.assert_admin();
  v_before  public.brands;
  v_brand   public.brands;
  v_website text;
begin
  select * into v_before from public.brands where id = p_brand_id for update;
  if not found then
    raise exception 'brand not found' using errcode = 'P0002';
  end if;

  if p_name is not null and length(btrim(p_name)) = 0 then
    raise exception 'brand name cannot be empty' using errcode = 'P0001';
  end if;
  if p_name is not null and length(btrim(p_name)) > 200 then
    raise exception 'brand name must be 200 characters or fewer' using errcode = 'P0001';
  end if;

  if p_website is not null then
    v_website := nullif(btrim(p_website), '');
    if v_website is not null and v_website !~* '^https?://' then
      raise exception 'website must be a full http(s) URL' using errcode = 'P0001';
    end if;
  end if;

  update public.brands
     set name       = coalesce(nullif(btrim(coalesce(p_name, '')), ''), name),
         poc_name   = case when p_poc_name   is null then poc_name   else nullif(btrim(p_poc_name),   '') end,
         poc_number = case when p_poc_number is null then poc_number else nullif(btrim(p_poc_number), '') end,
         poc_email  = case when p_poc_email  is null then poc_email  else nullif(btrim(p_poc_email),  '') end,
         website    = case when p_website    is null then website    else v_website end
   where id = p_brand_id
   returning * into v_brand;

  insert into public.audit_log (admin_id, action, target_table, target_id, details)
  values (
    v_admin,
    'update_brand',
    'brands',
    p_brand_id,
    jsonb_build_object(
      'before', jsonb_build_object(
        'name', v_before.name, 'poc_name', v_before.poc_name,
        'poc_email', v_before.poc_email, 'website', v_before.website
      ),
      'after', jsonb_build_object(
        'name', v_brand.name, 'poc_name', v_brand.poc_name,
        'poc_email', v_brand.poc_email, 'website', v_brand.website
      )
    )
  );

  return v_brand;
end;
$$;

-- -----------------------------------------------------------------------------
-- admin_delete_brand
--
-- Blocked when any campaign (products.campaign text value) or product row still
-- references this brand by name. Since brand linkage is currently a text field
-- (not a FK), we block on name match as a conservative safety check.
-- When a brand_id FK is added to campaigns/products in a future migration, this
-- function should be updated to check that FK instead.
-- -----------------------------------------------------------------------------
create or replace function public.admin_delete_brand(p_brand_id uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_admin    uuid := public.assert_admin();
  v_brand    public.brands;
  v_products int;
begin
  select * into v_brand from public.brands where id = p_brand_id for update;
  if not found then
    raise exception 'brand not found' using errcode = 'P0002';
  end if;

  -- Block deletion when products still carry this brand name.
  select count(*)::int into v_products
    from public.products
   where brand = v_brand.name;

  if v_products > 0 then
    raise exception
      'cannot delete brand "%": it is used by % product(s). Remove or re-assign those products first.',
      v_brand.name, v_products
      using errcode = 'P0001';
  end if;

  delete from public.brands where id = p_brand_id;

  insert into public.audit_log (admin_id, action, target_table, target_id, details)
  values (
    v_admin,
    'delete_brand',
    'brands',
    p_brand_id,
    jsonb_build_object('name', v_brand.name)
  );
end;
$$;

-- -----------------------------------------------------------------------------
-- Grants — same pattern as admin_create_product / admin_update_product.
-- assert_admin() re-checks inside the function body; these grants allow the
-- authenticated role to call the RPC at all.
-- -----------------------------------------------------------------------------
revoke all on function public.admin_create_brand(text, text, text, text, text) from public;
revoke all on function public.admin_update_brand(uuid, text, text, text, text, text) from public;
revoke all on function public.admin_delete_brand(uuid) from public;

revoke execute on function public.admin_create_brand(text, text, text, text, text) from anon;
revoke execute on function public.admin_update_brand(uuid, text, text, text, text, text) from anon;
revoke execute on function public.admin_delete_brand(uuid) from anon;

grant execute on function public.admin_create_brand(text, text, text, text, text) to authenticated;
grant execute on function public.admin_update_brand(uuid, text, text, text, text, text) to authenticated;
grant execute on function public.admin_delete_brand(uuid) to authenticated;


-- ----------------------------------------------------------------------------
-- >>> 0012_campaigns.sql
-- ----------------------------------------------------------------------------
-- =============================================================================
-- 0012  Campaigns.
--
-- A campaign is a (brand, number) pair — e.g. boAt × Campaign 3.
-- Numbers are 1-10, unique per brand, enforced both by a CHECK constraint and
-- by the UNIQUE index.  The admin_create_campaign RPC checks the pair does not
-- already exist before inserting, giving a clean error message instead of a
-- raw unique-violation.
--
-- brand_id is a hard FK with ON DELETE RESTRICT so a brand row cannot be
-- dropped while it still has campaigns.  (admin_delete_brand already blocks
-- on product name-match; this covers the campaigns side at the schema level.)
--
-- RLS / audit pattern mirrors 0011 (brands) exactly.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- Table
-- -----------------------------------------------------------------------------
create table if not exists public.campaigns (
  id               uuid    primary key default gen_random_uuid(),
  brand_id         uuid    not null references public.brands(id) on delete restrict,
  campaign_number  int     not null check (campaign_number between 1 and 10),
  created_by       uuid    references public.profiles(id),
  created_at       timestamptz not null default now(),
  unique (brand_id, campaign_number)
);

comment on table  public.campaigns                    is 'Brand × campaign-number pairs. Admin-only; no end-user access.';
comment on column public.campaigns.campaign_number    is 'Fixed ordinal 1-10 within the brand, enforced by CHECK and UNIQUE.';

-- -----------------------------------------------------------------------------
-- RLS — admin-only
-- -----------------------------------------------------------------------------
alter table public.campaigns enable row level security;

drop policy if exists campaigns_select_admin on public.campaigns;
drop policy if exists campaigns_insert_admin on public.campaigns;
drop policy if exists campaigns_delete_admin on public.campaigns;

create policy campaigns_select_admin on public.campaigns
  for select to authenticated
  using (public.is_admin());

create policy campaigns_insert_admin on public.campaigns
  for insert to authenticated
  with check (public.is_admin());

create policy campaigns_delete_admin on public.campaigns
  for delete to authenticated
  using (public.is_admin());

-- -----------------------------------------------------------------------------
-- admin_create_campaign
-- -----------------------------------------------------------------------------
create or replace function public.admin_create_campaign(
  p_brand_id        uuid,
  p_campaign_number int
)
returns public.campaigns
language plpgsql
security definer
set search_path = public
as $$
declare
  v_admin     uuid := public.assert_admin();
  v_brand     public.brands;
  v_campaign  public.campaigns;
begin
  -- Brand must exist.
  select * into v_brand from public.brands where id = p_brand_id;
  if not found then
    raise exception 'brand not found' using errcode = 'P0002';
  end if;

  -- Validate campaign number range.
  if p_campaign_number is null or p_campaign_number < 1 or p_campaign_number > 10 then
    raise exception 'campaign_number must be between 1 and 10' using errcode = 'P0001';
  end if;

  -- Give a clear message instead of a raw unique-violation.
  if exists (
    select 1 from public.campaigns
     where brand_id = p_brand_id
       and campaign_number = p_campaign_number
  ) then
    raise exception 'Campaign % is already registered for brand "%"',
      p_campaign_number, v_brand.name
      using errcode = 'P0001';
  end if;

  insert into public.campaigns (brand_id, campaign_number, created_by)
  values (p_brand_id, p_campaign_number, v_admin)
  returning * into v_campaign;

  insert into public.audit_log (admin_id, action, target_table, target_id, details)
  values (
    v_admin,
    'create_campaign',
    'campaigns',
    v_campaign.id,
    jsonb_build_object(
      'brand_id',        p_brand_id,
      'brand_name',      v_brand.name,
      'campaign_number', p_campaign_number
    )
  );

  return v_campaign;
end;
$$;

-- -----------------------------------------------------------------------------
-- admin_delete_campaign
-- -----------------------------------------------------------------------------
create or replace function public.admin_delete_campaign(p_campaign_id uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_admin     uuid := public.assert_admin();
  v_campaign  public.campaigns;
  v_brand     public.brands;
begin
  select * into v_campaign from public.campaigns where id = p_campaign_id for update;
  if not found then
    raise exception 'campaign not found' using errcode = 'P0002';
  end if;

  select name into v_brand from public.brands where id = v_campaign.brand_id;

  delete from public.campaigns where id = p_campaign_id;

  insert into public.audit_log (admin_id, action, target_table, target_id, details)
  values (
    v_admin,
    'delete_campaign',
    'campaigns',
    p_campaign_id,
    jsonb_build_object(
      'brand_id',        v_campaign.brand_id,
      'brand_name',      v_brand.name,
      'campaign_number', v_campaign.campaign_number
    )
  );
end;
$$;

-- -----------------------------------------------------------------------------
-- Grants
-- -----------------------------------------------------------------------------
revoke all on function public.admin_create_campaign(uuid, int) from public;
revoke all on function public.admin_delete_campaign(uuid) from public;

revoke execute on function public.admin_create_campaign(uuid, int) from anon;
revoke execute on function public.admin_delete_campaign(uuid) from anon;

grant execute on function public.admin_create_campaign(uuid, int) to authenticated;
grant execute on function public.admin_delete_campaign(uuid) to authenticated;


-- ----------------------------------------------------------------------------
-- >>> 0013_product_brand_campaign.sql
-- ----------------------------------------------------------------------------
-- =============================================================================
-- 0013  Link Products to Brands and Campaigns.
--
-- Adds nullable brand_id and campaign_id FK references to public.products,
-- while retaining legacy text columns (brand, campaign) for backward compatibility.
-- Updates admin_create_product and admin_update_product RPC signatures to accept
-- p_brand_id and p_campaign_id parameters.
-- =============================================================================

alter table public.products
  add column if not exists brand_id uuid references public.brands(id),
  add column if not exists campaign_id uuid references public.campaigns(id);

-- Drop old RPC signatures
drop function if exists public.admin_create_product(text, text, text, text, int, numeric, text, text, text, int);
drop function if exists public.admin_create_product(text, text, text, text, int, numeric, text, text, text, int, uuid, uuid);

create or replace function public.admin_create_product(
  p_name text,
  p_brand text default null,
  p_description text default null,
  p_image_url text default null,
  p_total_slots int default 1,
  p_cashback_amount numeric default null,
  p_product_link text default null,
  p_campaign text default null,
  p_asin_code text default null,
  p_daily_release_limit int default null,
  p_brand_id uuid default null,
  p_campaign_id uuid default null
)
returns public.products
language plpgsql
security definer
set search_path = public
as $$
declare
  v_admin uuid := public.assert_admin();
  v_product public.products;
  v_link text := nullif(btrim(coalesce(p_product_link, '')), '');
  v_campaign text := nullif(btrim(coalesce(p_campaign, '')), '');
  v_asin text := upper(nullif(btrim(coalesce(p_asin_code, '')), ''));
  v_limit int := nullif(p_daily_release_limit, 0);
begin
  if length(btrim(coalesce(p_name, ''))) = 0 then
    raise exception 'product name is required' using errcode = 'P0001';
  end if;
  if p_total_slots is null or p_total_slots < 1 or p_total_slots > 100000 then
    raise exception 'total_slots must be between 1 and 100000' using errcode = 'P0001';
  end if;
  if p_cashback_amount is not null and p_cashback_amount < 0 then
    raise exception 'cashback_amount cannot be negative' using errcode = 'P0001';
  end if;
  if v_link is not null and (length(v_link) > 1024 or v_link !~* '^https?://') then
    raise exception 'product_link must be a full http(s) URL' using errcode = 'P0001';
  end if;
  if v_campaign is not null and length(v_campaign) > 120 then
    raise exception 'campaign must be 120 characters or fewer' using errcode = 'P0001';
  end if;
  if v_asin is not null and v_asin !~ '^[A-Z0-9]{10}$' then
    raise exception 'asin_code must be exactly 10 letters or digits' using errcode = 'P0001';
  end if;
  if v_limit is not null and (v_limit < 1 or v_limit > 100000) then
    raise exception 'daily_release_limit must be between 1 and 100000 slots' using errcode = 'P0001';
  end if;

  insert into public.products (
    name, brand, description, image_url, total_slots, cashback_amount, status, created_by,
    product_link, campaign, asin_code, daily_release_limit, brand_id, campaign_id
  )
  values (
    btrim(p_name),
    nullif(btrim(coalesce(p_brand, '')), ''),
    nullif(btrim(coalesce(p_description, '')), ''),
    nullif(btrim(coalesce(p_image_url, '')), ''),
    p_total_slots,
    p_cashback_amount,
    'open',
    v_admin,
    v_link,
    v_campaign,
    v_asin,
    v_limit,
    p_brand_id,
    p_campaign_id
  )
  returning * into v_product;

  insert into public.audit_log (admin_id, action, target_table, target_id, details)
  values (
    v_admin,
    'create_product',
    'products',
    v_product.id,
    jsonb_build_object(
      'name', v_product.name,
      'brand', v_product.brand,
      'brand_id', v_product.brand_id,
      'campaign_id', v_product.campaign_id,
      'total_slots', v_product.total_slots,
      'released_slots', v_product.released_slots,
      'daily_release_limit', v_product.daily_release_limit,
      'cashback_amount', v_product.cashback_amount,
      'product_link', v_product.product_link,
      'campaign', v_product.campaign,
      'asin_code', v_product.asin_code
    )
  );

  return v_product;
end;
$$;

drop function if exists public.admin_update_product(uuid, text, text, text, text, int, numeric, text, text, text, text, int);
drop function if exists public.admin_update_product(uuid, text, text, text, text, int, numeric, text, text, text, text, int, uuid, uuid);

create or replace function public.admin_update_product(
  p_product_id uuid,
  p_name text default null,
  p_brand text default null,
  p_description text default null,
  p_image_url text default null,
  p_total_slots int default null,
  p_cashback_amount numeric default null,
  p_status text default null,
  p_product_link text default null,
  p_campaign text default null,
  p_asin_code text default null,
  p_daily_release_limit int default null,
  p_brand_id uuid default null,
  p_campaign_id uuid default null
)
returns public.products
language plpgsql
security definer
set search_path = public
as $$
declare
  v_admin uuid := public.assert_admin();
  v_before public.products;
  v_product public.products;
  v_link text;
  v_campaign text;
  v_asin text;
begin
  select * into v_before from public.products where id = p_product_id for update;
  if not found then
    raise exception 'product not found' using errcode = 'P0002';
  end if;

  if p_status is not null and p_status not in ('open', 'closed') then
    raise exception 'invalid product status' using errcode = 'P0001';
  end if;
  if p_name is not null and length(btrim(p_name)) = 0 then
    raise exception 'product name cannot be empty' using errcode = 'P0001';
  end if;
  if p_total_slots is not null and (p_total_slots < 1 or p_total_slots > 100000) then
    raise exception 'total_slots must be between 1 and 100000' using errcode = 'P0001';
  end if;
  if p_total_slots is not null and p_total_slots < v_before.slots_filled then
    raise exception 'total_slots cannot be lower than the % slots already filled', v_before.slots_filled
      using errcode = 'P0001';
  end if;
  if p_cashback_amount is not null and p_cashback_amount < 0 then
    raise exception 'cashback_amount cannot be negative' using errcode = 'P0001';
  end if;
  if p_daily_release_limit is not null
     and (p_daily_release_limit < 0 or p_daily_release_limit > 100000)
  then
    raise exception 'daily_release_limit must be between 1 and 100000 slots, or 0 to remove it'
      using errcode = 'P0001';
  end if;

  if p_product_link is not null then
    v_link := nullif(btrim(p_product_link), '');
    if v_link is not null and (length(v_link) > 1024 or v_link !~* '^https?://') then
      raise exception 'product_link must be a full http(s) URL' using errcode = 'P0001';
    end if;
  end if;

  if p_campaign is not null then
    v_campaign := nullif(btrim(p_campaign), '');
    if v_campaign is not null and length(v_campaign) > 120 then
      raise exception 'campaign must be 120 characters or fewer' using errcode = 'P0001';
    end if;
  end if;

  if p_asin_code is not null then
    v_asin := upper(nullif(btrim(p_asin_code), ''));
    if v_asin is not null and v_asin !~ '^[A-Z0-9]{10}$' then
      raise exception 'asin_code must be exactly 10 letters or digits' using errcode = 'P0001';
    end if;
  end if;

  update public.products
     set name = coalesce(nullif(btrim(coalesce(p_name, '')), ''), name),
         brand = case when p_brand is null then brand else nullif(btrim(p_brand), '') end,
         description = case when p_description is null then description else nullif(btrim(p_description), '') end,
         image_url = case when p_image_url is null then image_url else nullif(btrim(p_image_url), '') end,
         total_slots = coalesce(p_total_slots, total_slots),
         released_slots = least(released_slots, coalesce(p_total_slots, total_slots)),
         cashback_amount = coalesce(p_cashback_amount, cashback_amount),
         status = coalesce(p_status, status),
         product_link = case when p_product_link is null then product_link else v_link end,
         campaign = case when p_campaign is null then campaign else v_campaign end,
         asin_code = case when p_asin_code is null then asin_code else v_asin end,
         daily_release_limit = case
           when p_daily_release_limit is null then daily_release_limit
           when p_daily_release_limit = 0 then null
           else p_daily_release_limit
         end,
         brand_id = case when p_brand_id is null then brand_id else p_brand_id end,
         campaign_id = case when p_campaign_id is null then campaign_id else p_campaign_id end
   where id = p_product_id
   returning * into v_product;

  insert into public.audit_log (admin_id, action, target_table, target_id, details)
  values (
    v_admin,
    case
      when p_status = 'closed' and v_before.status <> 'closed' then 'close_product'
      when p_status = 'open' and v_before.status <> 'open' then 'reopen_product'
      else 'update_product'
    end,
    'products',
    p_product_id,
    jsonb_build_object(
      'before', jsonb_build_object(
        'name', v_before.name, 'brand', v_before.brand, 'brand_id', v_before.brand_id, 'campaign_id', v_before.campaign_id,
        'total_slots', v_before.total_slots, 'released_slots', v_before.released_slots,
        'daily_release_limit', v_before.daily_release_limit,
        'cashback_amount', v_before.cashback_amount, 'status', v_before.status,
        'product_link', v_before.product_link, 'campaign', v_before.campaign,
        'asin_code', v_before.asin_code
      ),
      'after', jsonb_build_object(
        'name', v_product.name, 'brand', v_product.brand, 'brand_id', v_product.brand_id, 'campaign_id', v_product.campaign_id,
        'total_slots', v_product.total_slots, 'released_slots', v_product.released_slots,
        'daily_release_limit', v_product.daily_release_limit,
        'cashback_amount', v_product.cashback_amount, 'status', v_product.status,
        'product_link', v_product.product_link, 'campaign', v_product.campaign,
        'asin_code', v_product.asin_code
      )
    )
  );

  return v_product;
end;
$$;

revoke all on function public.admin_create_product(text, text, text, text, int, numeric, text, text, text, int, uuid, uuid) from public;
revoke all on function public.admin_update_product(uuid, text, text, text, text, int, numeric, text, text, text, text, int, uuid, uuid) from public;
revoke execute on function public.admin_create_product(text, text, text, text, int, numeric, text, text, text, int, uuid, uuid) from anon;
revoke execute on function public.admin_update_product(uuid, text, text, text, text, int, numeric, text, text, text, text, int, uuid, uuid) from anon;
grant execute on function public.admin_create_product(text, text, text, text, int, numeric, text, text, text, int, uuid, uuid) to authenticated;
grant execute on function public.admin_update_product(uuid, text, text, text, text, int, numeric, text, text, text, text, int, uuid, uuid) to authenticated;
